modules["@src/automation/loader"] = function()
--[[
    suup twan
]]

local auto_start_flags = {
    "auto_saramed",
    "soup_echofarm",
    "flask_echofarm",

    "autoecho_titus",
    "auto_titus",
    "auto_echo_layer2",
    "ministry_notefarm",
    "auto_moonseyrie",
    'auto_layertwo',
    'auto_ferryman',
    'auto_authority_missions',
    'auto_duke',
    'auto_escape_depths',
    'auto_progress',
    'auto_voi'
}
    
local loader = {
    initialize = function()
        for _, farm in list_modules("automation/persistent_tasks/*") do
            local farm_module = require(farm);
    
            if farm_module and typeof(farm_module) == "table" and farm_module.persistent_data_flag then
                aztup.farms[farm_module.id] = farm_module;
                continue;
            end;
        end;
    end,
    
    should_auto_start = function(self)
        for _, flag in pairs(auto_start_flags) do
            if persistent_data:get(flag, false) == true then
                return true;
            end;
        end;
     
        return false;
    end,

    has_any = function(self)
        for _, farm in pairs(aztup.farms) do
            if persistent_data:get(farm.persistent_data_flag, false) ~= true then
                continue;
            end;
    
            return true;
        end;
    
        return false;
    end,
    
    set = function(self, flag, on)
        persistent_data:set(flag, on)
        self:start();
    end,

    start = function(self)
        if not services.NetworkClient:FindFirstChild("ClientReplicator") then
            return server_utility:quick_hop()
        end;
        
        local hopping = false;
        services.GuiService.ErrorMessageChanged:Connect(function()	
            if hopping or getgenv().dont_auto_hop_pls then return; end
            if not aztup.automation:has_any() then return; end
			local Code = services.GuiService:GetErrorCode().Value
	
			if Code >= Enum.ConnectionError.DisconnectErrors.Value then
                task.wait(60);
                hopping = true;
	            return server_utility:quick_hop()
			end
		end);

        local should_anti_afk;
        for _, farm in pairs(aztup.farms) do
            if not persistent_data:get(farm.persistent_data_flag, false) then
                continue;
            end;

            if farm.not_allowed and farm:not_allowed() then
                continue;
            end;
            
            should_anti_afk = true;
            task.spawn(function()
                farm:run();
            end);
        end;

        if should_anti_afk then
            task.spawn(function()
                local vim = Instance.new('VirtualInputManager') 

                while task.wait(120) do
                    vim:SendKeyEvent(true, Enum.KeyCode.Unknown, false, game)
                    task.wait(0.1)
                    vim:SendKeyEvent(false, Enum.KeyCode.Unknown, false, game)
                    task.wait(0.1)
                end
            end)
            require("@src/automation/exit_ui");
        end
    end
};

return loader;
end;

modules["@src/automation/persistent_tasks/auto_authority"] = function()
if is_regular then
    return {
        run = function()
            local_player.instance:Kick("Attempted to start a beta-only automation whilst not on beta.");
            persistent_data:wipe();
        end
    }
end;
local Safety = require('@src/utility/safety')
local automation_struct = require("@src/automation/struct");

local struct;
struct = automation_struct:construct({
    persistent_data_store = 'auto_authority_missions_store',
    persistent_data_flag = 'auto_authority_missions',
    id = 'auto_authority_missions',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start',    from = 'idle', to = '_check_area'},
            {name = 'continuation', from = '_check_area', to = '_check_area'}  
        },
        callbacks = {
            onenter_check_area = function(self)
                if is_etrean then
                    -- Hop to eastern
                    return
                end
                
                if is_eastern then
                    local args = {
                        "FriendlyFire",
                        true
                    }
                    game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("UpdateUXSettings"):FireServer(unpack(args))

                    aztup.flags.aa_bypass = true

                    local current_tween;
                    services.RunService.PostSimulation:Connect(function()
                        if Safety:PlayersNear(local_player.root_part, 300) > 0 then
                            if not EffectReplicator:HasEffect("Danger") then
                                local slot = local_player.instance:GetAttribute("DataSlot") or "A"
                                server_utility:hop(slot);
                            end;
                            
                            if current_tween then
                                current_tween:stop();
                            end
                            
                            local_player.root_part.CFrame = CFrame.new(local_player.root_part.CFrame.X, 3000,local_player.root_part.CFrame.Z);
                            return;
                        end;
                    end);
                    
                    local send_dialogue = game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue");
                    local destructibles = workspace:WaitForChild("Destructibles");
                    local npc_folder = workspace:WaitForChild("NPCs");
                    local terrain = workspace:WaitForChild("Terrain");
                    local live = workspace:WaitForChild("Live");
                    
                    local got = false;
                    local fc = 0;
                    send_dialogue.OnClientEvent:Connect(function(v273) 
                        got = not v273.exit;
                        fc += 1;
                    end);
                    
                    repeat 
                        task.wait()
                        current_tween = Tween.new(CFrame.new(-7502, 2000, 3481), true, 225).wait();
                        current_tween = Tween.new(CFrame.new(-7502, 11, 3481), true, 225).wait();
                        fireproximityprompt(npc_folder:WaitForChild("Captain Trist"):WaitForChild("InteractPrompt"))
                    until got;
                    local starting_fc = fc;
                    repeat 
                        task.wait()
                        send_dialogue:FireServer({
                            choice = "Yes, Sir."
                        })
                    until starting_fc ~= fc;
                    
                    task.spawn(function()
                        while got do
                            send_dialogue:FireServer({
                                exit = true
                            });
                            task.wait();
                        end;
                    end);
                    
                    local identified_job do
                        
                    end;
                    
                    local object;
                    InstanceWatcher.new(terrain, function(entity)
                        return entity:IsA("Attachment") and entity:WaitForChild("JobTrackerGui", 5)
                    end, function(entity)   
                        if object then return; end
                        
                        local job_tracker = entity:WaitForChild("JobTrackerGui");
                        local text_label = job_tracker:WaitForChild("TextLabel");
                        
                        if text_label then
                            identified_job = text_label.Text:find("Hostage") and "hostage" or text_label.Text:lower():find("secure") and "secure" or text_label.Text:find("Armanent Sabotage") and "barrels";
                            object = entity.CFrame;
                        end;
                    end);
                    
                    task.wait(2.5);
                    
                    local mission_dropdown = {
                        hostage = persistent_data:get('auto_authority_do_hostage', false),
                        barrels = persistent_data:get('auto_authority_do_barrels', false),
                        secure = persistent_data:get('auto_authority_do_secure', false),
                    };

                    if not identified_job or not mission_dropdown[identified_job] then
                        --Note: Rejoining is faster due to the fact we don't lose time on doing missions
                        local slot = local_player.instance:GetAttribute("DataSlot") or "A"
                        return server_utility:hop(slot);
                    end;
                    
                    local missions = {
                        hostage = function()
                            repeat
                                task.wait(0.5)
                                local args = {
                                    {
                                        exit = true
                                    }
                                }
                                game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
                            until not local_player.instance.PlayerGui.DialogueGui.Enabled
                            
                            current_tween = Tween.new(object * CFrame.new(0, 2000, 0), true, 225).wait();
                            current_tween = Tween.new(object, true, 225).wait();
                            
                            local hostage;
                            repeat task.wait()
                                for _, entity in live:GetChildren() do
                                    if not entity.Name:find(".hostage") then continue; end
                                    if not entity:FindFirstChild("HumanoidRootPart") then continue; end
                                    if (entity.HumanoidRootPart.Position - local_player.root_part.Position).Magnitude > 1000 then continue; end
                                    
                                    current_tween = Tween.new(entity.HumanoidRootPart.CFrame, true, 225).wait();
                                    hostage = entity;
                                    break;
                                end;
                            until hostage;
                            
                            current_tween = Tween.new(hostage.HumanoidRootPart.CFrame, true, 225).wait();
                            
                            local last_carry = 0;
                            local carrying_since = nil;
                            repeat
                                if EffectReplicator:FindEffect('Carrying') then
                                    carrying_since = carrying_since or tick();
                                else
                                    -- we dropped his ahh
                                    carrying_since = nil;
                                    local character_handler = local_player.character:FindFirstChild("CharacterHandler");
                                    local requests = character_handler and character_handler:FindFirstChild("Requests");
                                    local carry = requests and requests:FindFirstChild("Carry");

                                    if carry and tick() - last_carry > 0.75 then
                                        last_carry = tick();
                                        carry:FireServer();
                                    end;
                                end;
                                current_tween = Tween.new(hostage.HumanoidRootPart.CFrame, true, 225).wait();
                                task.wait();
                            until carrying_since and tick() - carrying_since >= 2;
                            
                            if EffectReplicator:FindEffect('Carrying') then
                                current_tween = Tween.new(CFrame.new(local_player.root_part.Position.X, 2000, local_player.root_part.Position.Z), true, 225).wait()
                            end
                            
                            repeat 
                                task.wait()
                                current_tween = Tween.new(CFrame.new(-7502, 2000, 3481), true, 225).wait();
                                current_tween = Tween.new(CFrame.new(-7502, 11, 3481), true, 225).wait();            
                                fireproximityprompt(npc_folder:WaitForChild("Captain Trist"):WaitForChild("InteractPrompt"))
                            until got;
                        end;
                        barrels = function()
                            repeat
                                task.wait(0.5)
                                local args = {
                                    {
                                        exit = true
                                    }
                                }
                                game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
                            until not local_player.instance.PlayerGui.DialogueGui.Enabled
                            
                            local character_handler = local_player.character:FindFirstChild("CharacterHandler");
                            character_handler.Requests.DrawWeapon:FireServer(true);
                            current_tween = Tween.new(object * CFrame.new(0,1500,0), true, 225).wait();
                            current_tween = Tween.new(object * CFrame.new(0,200,0), true, 225).wait();
                            while task.wait() do
                                local splash_gui = local_player.instance.PlayerGui:FindFirstChild("SplashGui");
                                local time_frame = splash_gui and splash_gui:FindFirstChild("TimeFrame");
                                local time_label = time_frame and time_frame:FindFirstChild("TimeText");
                                if time_label and time_label.Text:lower():find("report back") then
                                    break;
                                end;
                                
                                local crates = {};
                                for _, crate in destructibles:GetChildren() do
                                    if crate.Name:find("KhanCrate") and crate:IsA("Model") and (Vector3.new(crate:GetPivot().X, 0, crate:GetPivot().Z) - Vector3.new(local_player.root_part.Position.X, 0, local_player.root_part.Position.Z)).Magnitude < 1200 then
                                        table.insert(crates, crate);
                                    end;
                                end;
                                
                                table.sort(crates, function(a,b)
                                    return (a:GetPivot().Position - local_player.root_part.Position).Magnitude < (b:GetPivot().Position - local_player.root_part.Position).Magnitude
                                end);
                                
                                for _, crate in crates do
                                    while crate:GetAttribute("StructureHealth") and crate:GetAttribute("StructureHealth") > 0 do
                                        aztup.features.m1_hold.held = true;
                                        current_tween = Tween.new(CFrame.new((crate:GetPivot() * CFrame.new(0,-5,0)).Position) * CFrame.Angles(math.rad(90), 0, 0), true, 225).wait();
                                        
                                        task.wait();
                                    end;
                                    aztup.features.m1_hold.held = false;
                                end;
                            end;
                            
                            repeat 
                                task.wait()
                                current_tween = Tween.new(CFrame.new(-7502, 2000, 3481), true, 225).wait();
                                current_tween = Tween.new(CFrame.new(-7502, 11, 3481), true, 225).wait();
                                fireproximityprompt(npc_folder:WaitForChild("Captain Trist"):WaitForChild("InteractPrompt"))
                            until got;
                        end,
                        secure = function()
                            current_tween = Tween.new(object * CFrame.new(0,1500,0), true, 225).wait();
                            current_tween = Tween.new(object, true, 225).wait();
                    
                            local current_banner;
                            repeat task.wait()
                                for _, banner in workspace:GetChildren() do
                                    if banner.Name == "Authority Checkpoint" and banner:IsA("Model") and (Vector3.new(banner:GetPivot().X, 0, banner:GetPivot().Z) - Vector3.new(local_player.root_part.Position.X, 0, local_player.root_part.Position.Z)).Magnitude < 1200 then
                                        current_banner = banner;
                                    end;
                                end;
                            until current_banner;
                            while task.wait() do
                                Tween.new(current_banner:GetPivot() * CFrame.new(0, 8, 0), true, 225).wait();
                                local start = tick();
                                local stop = false;
                                repeat task.wait() 
                                    local splash_gui = local_player.instance.PlayerGui:FindFirstChild("SplashGui");
                                    local time_frame = splash_gui and splash_gui:FindFirstChild("TimeFrame");
                                    local time_label = time_frame and time_frame:FindFirstChild("TimeText");
                                    if time_label and time_label.Text:lower():find("report back") then
                                        stop = true;
                                        break;
                                    end;
                                until tick() - start > 35;
                                if stop then break; end;
                                repeat task.wait()
                                    local splash_gui = local_player.instance.PlayerGui:FindFirstChild("SplashGui");
                                    local time_frame = splash_gui and splash_gui:FindFirstChild("TimeFrame");
                                    local time_label = time_frame and time_frame:FindFirstChild("TimeText");
                                    if time_label and time_label.Text:lower():find("report back") then
                                        stop = true;
                                        break;
                                    end;
                                    Tween.new(current_banner:GetPivot() * CFrame.new(0, 3000, 0), true, 225).wait();
                                until tick() - start > 90 + 35;
                                if stop then break; end;
                                repeat task.wait()
                                    local splash_gui = local_player.instance.PlayerGui:FindFirstChild("SplashGui");
                                    local time_frame = splash_gui and splash_gui:FindFirstChild("TimeFrame");
                                    local time_label = time_frame and time_frame:FindFirstChild("TimeText");
                                    if time_label and time_label.Text:lower():find("report back") then
                                        stop = true;
                                        break;
                                    end;
                    
                                    Tween.new(current_banner:GetPivot() * CFrame.new(0, 8, 0), true, 225).wait();
                                until tick() - start > 120 + 35;
                                if stop then break; end;
                    
                                local splash_gui = local_player.instance.PlayerGui:FindFirstChild("SplashGui");
                                local time_frame = splash_gui and splash_gui:FindFirstChild("TimeFrame");
                                local time_label = time_frame and time_frame:FindFirstChild("TimeText");
                                if time_label and time_label.Text:lower():find("report back") then
                                    break;
                                end;
                            end
                    
                            
                            repeat 
                                task.wait()
                                current_tween = Tween.new(CFrame.new(-7502, 2000, 3481), true, 225).wait();
                                current_tween = Tween.new(CFrame.new(-7502, 11, 3481), true, 225).wait();
                                fireproximityprompt(npc_folder:WaitForChild("Captain Trist"):WaitForChild("InteractPrompt"))
                            until got;
                        end
                    }
                    
                    missions[identified_job]();
                    
                    repeat
                        task.wait(0.5)
                        local args = {
                            {
                                exit = true
                            }
                        }
                        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
                    until not local_player.instance.PlayerGui.DialogueGui.Enabled
                    
                    self:continuation()
                end
            end
        }
    }),
    features = {
        'fly',
        'noclip',
        'no_fall',
        'no_kill_bricks',
        'm1_hold',
        'no_fire',
        'auto_equip_weapon',

    },
    not_allowed = function()
        return false;
    end,
    character_creator_handler_used = false,
    character_creator_handler_opts = {}
})

return struct;
end;

modules["@src/automation/persistent_tasks/auto_deepdrill"] = function()
-- TODO: Add a way to detect if its the players first time doing the deep drill ( because the dialouge changes depending on that )

local automation_struct = require("@src/automation/struct");
local autofarm_util = require('@src/utility/deepwoken/autofarm_utilitys');
local struct;

local drill_npc_position = CFrame.new(-5217, 117, -5610);
local nest_waypoint = CFrame.new(-5312, 283, -4793);
local drill_site = CFrame.new(-4651.23877, 202.903076, -4486.12012, 0.939700544, -0, -0.341998369, 0, 1, -0, 0.341998369, 0, 0.939700544);

local auto_deepdrill = {
    temp_tween = function(cf, speed)
        Tween.new(cf, true, speed or 200).wait();
    end,

    server_hop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, true, true);
    end,

    player_check = function(mag, custom)
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if player == local_player.instance then continue end

            local hrp = player.Character:FindFirstChild("HumanoidRootPart");
            if not hrp then continue end

            local dist = ((custom or local_player.root_part.Position) - hrp.Position).Magnitude;
            if dist <= mag then
                return true;
            end
        end
        return false;
    end,

    player_safe_tween = function(self, cf, speed)
        if self.player_check(200) then
            self.server_hop();
            while task.wait() do end
        end

        self.temp_tween(cf, speed);

        if self.player_check(200, cf.Position) then
            self.server_hop();
            while task.wait() do end
        end
    end,

    send_dialogue = function(text, exit)
        local remote = game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue");
        local args = exit and { { exit = true } } or { { choice = text } };

        local acked = false;
        local conn = remote.OnClientEvent:Connect(function()
            acked = true;
        end);

        local attempts = 0;
        repeat
            remote:FireServer(unpack(args));
            attempts += 1;
            task.wait(0.5);
        until acked or attempts >= 6;

        conn:Disconnect();
    end,

    closest_npc = function()
        local npcs = workspace:FindFirstChild("NPCs");
        if not npcs then return nil end

        local closest, shortest = nil, math.huge;
        for _, npc in npcs:GetChildren() do
            if not npc:IsA("Model") then continue end

            local ok, position = pcall(function()
                return npc:GetPivot().Position;
            end);
            if not ok then continue end

            local dist = (position - local_player.root_part.Position).Magnitude;
            if dist < shortest then
                shortest = dist;
                closest = npc;
            end
        end

        return closest;
    end,
};

function auto_deepdrill:get_key()
    autofarm_util:ReadyWeapon(true);

    repeat
        pcall(function()
            self.temp_tween(workspace.NPCs:FindFirstChild('TheKey'):GetPivot(), 200);
        end);
        pcall(function()
            fireproximityprompt(workspace.NPCs.TheKey.InteractPrompt);
        end);
        task.wait(0.5);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    self.send_dialogue(nil, true);

    self.temp_tween(workspace.NPCs:FindFirstChild('TheDoor'):GetPivot(), 200);

    repeat
        self.temp_tween(workspace.NPCs:FindFirstChild('TheDoor'):GetPivot(), 200);
        pcall(function()
            fireproximityprompt(workspace.NPCs:FindFirstChild('TheDoor').InteractPrompt);
        end);
        task.wait(0.5);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    self.send_dialogue(nil, true);
end

function auto_deepdrill:void_bonekeeper()
    local bonekeeper_location = CFrame.new(-5747, 459, -6357);
    self.temp_tween(bonekeeper_location, 200);
    aztup_toggles.void_mobs:SetValue(true);

    local bonekeeper = nil;
    local real_bonekeeper = nil;

    repeat
        if not bonekeeper then
            self.temp_tween(CFrame.new(-5889, 459, -6308));
        end

        if real_bonekeeper and real_bonekeeper.Parent == nil and not bonekeeper then
            bonekeeper = nil;
            real_bonekeeper = nil;
            break;
        end

        for _, v in workspace.Live:GetChildren() do
            if v == local_player.character then continue end
            if not v.Name:find(".boneboy") then continue end
            real_bonekeeper = v;
            bonekeeper = v;
        end

        if not bonekeeper then
            self.temp_tween(bonekeeper_location);
        end

        task.wait();
    until bonekeeper;

    self.temp_tween(CFrame.new(-5788, 563, -6351), 200);

    repeat
        task.wait();
    until not workspace.EncounterTriggers:FindFirstChild('BonekeeperBridge')
        or (workspace.EncounterTriggers:FindFirstChild('BoneKeeperBridge') and not workspace.EncounterTriggers.BoneKeeperBridge:FindFirstChild('Barrier'));
end

function auto_deepdrill:turn_on_generator()
    self.temp_tween(CFrame.new(-5555, 529, -6475), 200);

    repeat
        self.temp_tween(CFrame.new(-5555, 529, -6475), 200);
        task.wait(0.5);
        pcall(function()
            fireproximityprompt(workspace.NPCs.TheGenerator.InteractPrompt);
        end);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    self.send_dialogue('[Restart it]');
    self.send_dialogue(nil, true);
    aztup_toggles.void_mobs:SetValue(false);
end

function auto_deepdrill:talk_to_drill_guy()
    self.player_safe_tween(self, drill_npc_position, 200);

    local npc;
    repeat
        npc = self.closest_npc();
        task.wait();
    until npc or not aztup.automation:has_any();

    if not npc then return false; end

    local prompt = npc:FindFirstChild("InteractPrompt", true);
    if not prompt then
        return false;
    end

    repeat
        pcall(function()
            self.temp_tween(npc:GetPivot(), 200);
        end);
        pcall(function()
            fireproximityprompt(prompt);
        end);
        task.wait(0.5);
    until (local_player.instance.PlayerGui:FindFirstChild("DialogueGui") and local_player.instance.PlayerGui.DialogueGui.Enabled)
        or not aztup.automation:has_any();

    if not aztup.automation:has_any() then return false; end

    self.send_dialogue("You got a drill ready?");
    self.send_dialogue("Where can I find it?");
    self.send_dialogue(nil, true);

    return true;
end

function auto_deepdrill:enter_drill_site()
    self.player_safe_tween(self, nest_waypoint, 200);
    task.wait(0.5);
    self.player_safe_tween(self, drill_site, 200);
end

function auto_deepdrill:wait_for_teleport_out()
    repeat
        task.wait(1);
    until not local_player.root_part
end

local state_machine = StateMachine.create({
    initial = "idle",
    events = {
        { name = "start",       from = "idle",              to = "_get_key" },
        { name = "void",        from = "_get_key",           to = "_void_bonekeeper" },
        { name = "generator",   from = "_void_bonekeeper",    to = "_turn_on_generator" },
        { name = "talk",        from = "_turn_on_generator",  to = "_talk_to_npc" },
        { name = "enter",       from = "_talk_to_npc",        to = "_enter_site" },
        { name = "arrived",     from = "_enter_site",         to = "_arrived" },
        { name = "restart",     from = "_arrived",            to = "_get_key" },
    },

    callbacks = {
        onenter_get_key = function(self)
            auto_deepdrill:get_key();

            if aztup.automation:has_any() then
                self:void();
            end;
        end,

        onenter_void_bonekeeper = function(self)
            auto_deepdrill:void_bonekeeper();

            if aztup.automation:has_any() then
                self:generator();
            end;
        end,

        onenter_turn_on_generator = function(self)
            auto_deepdrill:turn_on_generator();

            if aztup.automation:has_any() then
                self:talk();
            end;
        end,

        onenter_talk_to_npc = function(self)
            local ok = auto_deepdrill:talk_to_drill_guy();

            if ok and aztup.automation:has_any() then
                self:enter();
            end;
        end,

        onenter_enter_site = function(self)
            auto_deepdrill:enter_drill_site();

            if aztup.automation:has_any() then
                self:arrived();
            end;
        end,

        onenter_arrived = function(self)
            auto_deepdrill:wait_for_teleport_out();

            if aztup.automation:has_any() then
                self:restart();
            end;
        end,
    }
});

struct = automation_struct:construct({
    persistent_data_store = "auto_deepdrill_store",
    persistent_data_flag  = "auto_deepdrill",
    id = "auto_deepdrill",

    state_machine = state_machine,

    features = {
        "no_fall",
        "noclip",
        "fly",
        "auto_equip_weapon",
        "void_mobs",
        "no_kill_bricks"
    },

    not_allowed = function()
        return false;
    end,

    on_run = function()
        if is_depths then
            persistent_data:wipe();
            local_player.instance:Kick("done :)");
        end;
    end,

    character_creator_handler_used = false,
    character_creator_handler_opts = {},
});

return struct;
end;

modules["@src/automation/persistent_tasks/auto_duke"] = function()
--!nocheck
if is_regular then
    return {
        run = function()
            local_player.instance:Kick("Attempted to start a beta-only automation whilst not on beta.");
            persistent_data:wipe();
        end
    }
end;
local automation_struct = require("@src/automation/struct");

local hold_m1 = false

local autoduke = {
    temp_tween = function(cf, speed)
        Tween.new(cf, true, speed).wait();
    end,
    player_safe_tween = function(self, cf, speed)
        if self.player_near() then
            -- Serverhop to small server, will kick for now
            self.server_hop()
            while task.wait() do end
        end
        
        local ylevel = math.random(8000, 10000)
        
        -- Tween up
        local_player.root_part.CFrame = local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0)
        --self.tempTween(local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0), speed)
        
        -- Tween to target location
        self.temp_tween(cf + Vector3.new(0, cf.Y + ylevel, 0), speed)
        
        -- Check for players
        if self.players_near(Vector3.new(cf.X, cf.Y, cf.Z), 200) then
            -- Serverhop to small server, will kick for now
            self.server_hop()
            while task.wait() do end
        end
        
        -- Tween down
        local_player.root_part.CFrame = cf
        task.wait(1)
    end,
    player_near = function()
        for _, player in services.Players:GetPlayers() do
            if local_player.instance == player then continue end
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            
            local dist = (local_player.root_part.Position - player.Character:GetPivot().Position).Magnitude
            if dist <= 1000 then return true end
        end
        
        return false
    end,
    players_near = function(target, mag)
        mag = mag or 1000;
        target = target or local_player.root_part.Position;
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            if player == local_player.instance then continue end
            
            local hmrp = player.Character.HumanoidRootPart
            
            local dist = (target - player.Character:GetPivot().Position).Magnitude
            
            if (dist <= mag) then
                return true
            end
        end
        
        return false
    end,
    server_hop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, true, true)
    end,
    m1_hold = function(toggle)
        if not toggle then
            hold_m1 = false
            return
        end
        
        hold_m1 = true
    end,
    ready_weapon = function()
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        character_handler.Requests.DrawWeapon:FireServer(true);
    end,
    grab_chests = function(self)
        local looted = false;
        local time = 3
        local secondsWaited = 0
        
        for _, chest in pairs(workspace.Thrown:GetChildren()) do
            if not chest:FindFirstChild("Lid") then continue; end
            if services.CollectionService:HasTag(chest, 'looted') then continue end
            
            self.temp_tween(chest.Lid.CFrame, 170)
            local moreTime = 3
            local moreSecondsWaited = 0
            
            repeat 
                task.wait(1) 
                pcall(function()
                    fireproximityprompt(chest:FindFirstChildWhichIsA("ProximityPrompt"));
                end);
                pcall(function(...) 
                    self.temp_tween(chest.Lid.CFrame, 170)
                end)
                moreSecondsWaited += 1
            until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or not aztup.automation:has_any() or moreSecondsWaited >= moreTime
            if local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') then
                looted = true;
            end;

            repeat task.wait(1); secondsWaited += 1; until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or not aztup.automation:has_any() or secondsWaited >= time
            
            if local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') then
                looted = true;
                pcall(function(...)  
                    local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt'):FindFirstChild('Choice'):FireServer('EXIT')
                end)
            end

            services.CollectionService:AddTag(chest, 'looted')
        end
        return looted;
    end,
}

function autoduke:refill()
    local function collect_ingredient(ing)
        self.player_safe_tween(self, ing.CFrame, 200)
        local cf = ing.CFrame;

        repeat
            Tween.new(cf, true).wait();

            pcall(function(...)  
                fireproximityprompt(ing:FindFirstChildOfClass('ProximityPrompt'))
            end)
            task.wait()
        until ing.Parent == nil
    end
    
    local function eat_food(food)
        local food_item = local_player.instance.Backpack:FindFirstChild(food);
        if not food_item then return end

        local_player.character.Humanoid:EquipTool(food_item)
        food_item:Activate();
        task.wait(0.5);
        local_player.character.Humanoid:UnequipTools();
    end
    
    local function isSatiated()
        local water = local_player.character:FindFirstChild('Water')
        return (water.Value >= (water.MaxValue * 0.5))
    end
    
    local function get_closest_ingredient(ing)
        local closest = nil
        
        for _, ingredient in workspace.Ingredients:GetChildren() do
            if not ingredient.Name:match(ing) then continue end
            
            if closest == nil then
                closest = ingredient
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest.Position).Magnitude
                local ingDist = (local_player.root_part.Position - ingredient.Position).Magnitude
                
                if closestDist > ingDist then
                    closest = ingredient
                end
            end
        end
        
        return closest
    end
    
    --why is TEMPED SO FUCKING GOATED?, i dunno G!!!!!!
    
    local start_tick = tick();
    local has_carnivore = local_player.character:GetAttribute("ssv_Passives") and local_player.character:GetAttribute("ssv_Passives"):find("Carnivore")
    if not has_carnivore then
        if not isSatiated() then
            while not isSatiated() and tick() - start_tick <= 45 do
                local ing = get_closest_ingredient('Dentifilo') or get_closest_ingredient('Calabash');
                if ing then
                    collect_ingredient(ing) -- probably the safest food in the etrean luminant
                    eat_food(ing.Name)
                else
                    break;
                end

                task.wait();
            end;
        end
    end
end

function autoduke:create_instance()
    local backpack = local_player.instance:FindFirstChild("Backpack");
    if not backpack then return; end

    local manor_key = backpack:WaitForChild("Manor Key", 10) or local_player.character:WaitForChild("Manor Key", 10) 
    if not manor_key then return Logger:notify_sound("need manor key"); end

    manor_key.Parent = local_player.character;

    local handle = manor_key:WaitForChild("Handle", 10);
    if not handle then return local_player.instance:Kick("failsafe [1]"); end

    --run this in a seperate routine - we really do not actually care about the end result
    if handle.Color.R < 0.99 or handle.Color.G < 0.99 or handle.Color.B < 0.99 then
        local start = tick();
        local old = handle.Color;
        repeat task.wait() until handle.Color ~= old or tick() - start > 10;
        if handle.Color.R < 0.99 or handle.Color.G < 0.99 or handle.Color.B < 0.99 then 
            return self.server_hop();
        end
    end
    
    self:player_safe_tween(CFrame.new(1460, 74, 3069), 200);
    
    local started = false;
    task.delay(20, function() 
        if started then return; end

        local slot = local_player.instance:GetAttribute("DataSlot");
        return server_utility:hop(slot, true);
    end)

    workspace.Live.ChildAdded:Connect(function(entity)
        if not (entity.Name:find("brainsucker") or entity.Name:find("dukecultist")) then return; end
        if (entity:GetPivot().Position - local_player.root_part.Position).Magnitude > 400 then return; end
        started = true;
    end)

    while task.wait() and not started do    
        sethiddenproperty(local_player.humanoid, "MoveDirectionInternal", Vector3.one)
        fireproximityprompt(workspace:WaitForChild("Doors"):WaitForChild("ErisiaDungeonGate"):WaitForChild("Main"):WaitForChild("InteractPrompt"));
        task.wait();
    end;

    services.RunService.Heartbeat:Connect(function() 
        aztup.features.m1_hold.held = hold_m1
    end)

    self:ready_weapon();
    self:m1_hold(true);
    
    local done = false;
    while task.wait() and not done do
        done = true;
        for _, entity in workspace.Live:GetChildren() do
            if not (entity.Name:find("brainsucker") or entity.Name:find("dukecultist")) then continue; end
            if (entity:GetPivot().Position - local_player.root_part.Position).Magnitude > 900 then continue; end

            local humanoid = entity:FindFirstChildOfClass("Humanoid");

            while humanoid and humanoid.Health > 0 and entity:FindFirstChild("HumanoidRootPart") do
                if self.player_near() then
                    self.server_hop()
                    while task.wait() do end
                end

                if not entity:FindFirstChild("HumanoidRootPart") then 
                    task.wait();
                    continue; 
                end

                aztup.features.m1_hold.held = true;
                Tween.new(entity.HumanoidRootPart.CFrame * CFrame.new(0, 0, 3), true, 250).wait();
                task.wait();
            end

            done = false;
        end
    end
    self:m1_hold(false);

    task.delay(30, function() 
        local slot = local_player.instance:GetAttribute("DataSlot");
        return server_utility:hop(slot, true);
    end)

    self:player_safe_tween(CFrame.new(1470, 84, 3586), 200);
    for i = 1, 300 do
        if self.player_near() then
            -- Serverhop to small server, will kick for now
            self.server_hop()
            while task.wait() do end
        end

        Tween.new(CFrame.new(1470, 84, 3586), true, 250).wait();
        fireproximityprompt(workspace.ErisiaElevator.Switch.InteractPrompt);
        task.wait(0.1);
    end;
    return true;
end

function autoduke:kill_duke()
    services.RunService.Heartbeat:Connect(function() 
        aztup.features.m1_hold.held = hold_m1
    end)

    self:ready_weapon();
    self:m1_hold(true);

    local client_effect;
    repeat 
        client_effect = services.ReplicatedStorage:FindFirstChild("ClientEffect", true)

        if not client_effect then
            task.wait()
        else break; end
    until client_effect;

    local nope_tf_out = false;
    client_effect.OnClientEvent:Connect(function(effectName, effectData)
        if effectName == "GolemLaserFire" then
            nope_tf_out = true;
            task.delay(0.4, function() 
                nope_tf_out = false;
            end)
        end
    end)

    local done = false;
    while task.wait() and not done do
        done = true;
        for _, entity in workspace.Live:GetChildren() do
            if not persistent_data:get("auto_duke") then break; end
            if not (entity.Name:find("prime_golem") or entity.Name:find("dukecultist")) then continue; end
            if (entity:GetPivot().Position - local_player.root_part.Position).Magnitude > 900 then continue; end
            if entity:GetPivot().Z < 2000 then continue; end

            local humanoid = entity:FindFirstChildOfClass("Humanoid");

            while humanoid and humanoid.Health > 0 do
                if game:GetService("UserInputService"):IsKeyDown(Enum.KeyCode.U) then break; end
                self:m1_hold(true);

                if not entity:FindFirstChild("HumanoidRootPart") then break; end
                if not nope_tf_out then
                    Tween.new(entity.HumanoidRootPart.CFrame * (entity.Name:find("prime_golem") and CFrame.new(0, 5, 0.35) or CFrame.new(0,2,3)), true, 250).wait();
                else
                    Tween.new(entity.HumanoidRootPart.CFrame * CFrame.new(0, 100, 10), true, 250).wait();
                end

                task.wait();
            end

            done = false;
        end
        if not persistent_data:get("auto_duke") then break; end

    end
            if not persistent_data:get("auto_duke") then return; end

    self:m1_hold(false);

    --if voiding_mode then you have to do the fight for him to void lol
    --    Tween.new(CFrame.new(2495, 139, 1926), true, 200).wait();
    --    task.delay(30, function()
    --        repeat 
    --            task.wait() 
    --            Tween.new(CFrame.new(2495, 139, 1926), true, 200).wait();
    --        until not EffectReplicator:FindEffect("Danger");
    --        require("@src/features/buttons/respawn")();
    --    end)
--
    --    while not self:grab_chests() do
    --        Tween.new(CFrame.new(2495, 139, 1926), true, 200).wait();
    --        local_player.root_part.Veloicty = Vector3.zero;
    --        task.wait(1);
    --    end;
    --    return;
    --end

    local send_dialogue = game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue");
    local got = false;
    local fc = 0;
    send_dialogue.OnClientEvent:Connect(function(v273) 
        got = not v273.exit;
        fc += 1;
    end);

    if not shared.a then
        repeat 
            Instance.new("VirtualInputManager"):SendKeyEvent(false, Enum.KeyCode.One, false, game)
            task.wait() 
            Tween.new(workspace.Live:WaitForChild(".theduke11"):WaitForChild("HumanoidRootPart").CFrame * CFrame.new(0, 0, 3), true, 250).wait();
            fireproximityprompt(workspace.Live[".theduke11"]:WaitForChild("InteractPrompt"));
            Instance.new("VirtualInputManager"):SendKeyEvent(true, Enum.KeyCode.One, false, game)
        until got;
    end;

    shared.a = true;
    while got do 
        Instance.new("VirtualInputManager"):SendKeyEvent(false, Enum.KeyCode.One, false, game)
        task.wait() 
        Instance.new("VirtualInputManager"):SendKeyEvent(true, Enum.KeyCode.One, false, game)
        task.wait() 
    end;
    
    repeat task.wait() until workspace.Live[".theduke11"]:FindFirstChild("Target") and workspace.Live[".theduke11"]:FindFirstChild("Target").Value;
    self:ready_weapon();
    task.delay(5, function()
        workspace.Live:FindFirstChild(".theduke11").Humanoid.AnimationPlayed:Connect(function(anim)
            if anim.Animation.AnimationId:find("8275408994") or anim.Animation.AnimationId:find("8290899374") or anim.Animation.AnimationId:find("8294560344") then
                nope_tf_out = true;
                task.delay(anim.Animation.AnimationId:find("8294560344") and 7.5 or 2.5, function() 
                    nope_tf_out = false;
                end)
            end
        end)
    end)

    local voiding_mode = persistent_data:get("auto_duke_voids", false);
    aztup_toggles.void_mobs:SetValue(voiding_mode);

    local duke = workspace.Live[".theduke11"]
    while workspace.Live:FindFirstChild(".theduke11") do
        task.wait();
        self:m1_hold(not general:playing_ap_anims(workspace.Live[".theduke11"]));

            if not persistent_data:get("auto_duke") then break; end 
        if not duke:FindFirstChild("HumanoidRootPart") or not duke:FindFirstChild("Humanoid") or not duke.Parent or duke.Humanoid.Health <= 0 then break; end
        
        if voiding_mode and not nope_tf_out and not general:playing_ap_anims(workspace.Live[".theduke11"]) and game:GetService("Players").LocalPlayer.Backpack:FindFirstChild("Mantra:ChokeIce{{Frost Grab}}") then 
            local Event = local_player.character.CharacterHandler.Requests.ActivateMantra
            Event:FireServer(
                game:GetService("Players").LocalPlayer.Backpack:FindFirstChild("Mantra:ChokeIce{{Frost Grab}}")
            )
        end;

        if workspace.Live[".theduke11"].HumanoidRootPart.CFrame.Y <= -1000 then continue; end --[[continue because void can <bold>fail</bold>]]
        
        local x, y, z = select(1, workspace.Live[".theduke11"].HumanoidRootPart.CFrame:GetComponents());
        local x_sin = math.sin(tick() * 2) * 30;
        local z_cos = math.cos(tick() * 2) * 30;
        if general:playing_ap_anims(workspace.Live[".theduke11"], {
            "rbxassetid://8085349676"
        }) or nope_tf_out then
            KeyHandler:get_key("CriticalClick"):FireServer({
                S = false,
                NOAERIALS = false, 
                Space = false,
                Right = false,
                W = false,
                Left = true
            }, false);
            Tween.new(CFrame.new(x + x_sin, y < 70 and math.random(175, 250) or math.random(0, 10), z + z_cos), true, 250).wait();
        elseif general:playing_ap_anims(workspace.Live[".theduke11"]) then
            --Tween.new(workspace.Live[".theduke11"].HumanoidRootPart.CFrame * CFrame.new(0, 6, 0) * CFrame.Angles(math.rad(-90), 0, 0), true, 250).wait();        
            Tween.new(CFrame.new(x + x_sin, y < 70 and math.random(175, 250) or math.random(0, 10), z + z_cos), true, 250).wait();
        else
            Tween.new(workspace.Live[".theduke11"].HumanoidRootPart.CFrame * CFrame.new(0, -6, 0) * CFrame.Angles(math.rad(90), 0, 0), true, 250).wait();        
        end
    end
    print("done");
    self:m1_hold(false)

    task.delay(60 * 5, function()
        repeat 
            task.wait() 
            Tween.new(CFrame.new(2495, 139, 1926), true, 160).wait();
        until not EffectReplicator:FindEffect("Danger");
        require("@src/features/buttons/respawn")();
    end)

    while true do
        local suc, res = pcall(function() 
            return self:grab_chests()
        end);

        if suc and res then break; end
        task.wait(1);
    end
    
    repeat 
        task.wait() 
        Tween.new(CFrame.new(2495, 139, 1926), true, 160).wait();
    until not EffectReplicator:FindEffect("Danger");
    require("@src/features/buttons/respawn")();
end

local struct;
struct = automation_struct:construct({
    persistent_data_store = 'auto_duke_store',
    persistent_data_flag = 'auto_duke',
    id = 'auto_duke',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start',    from = 'idle', to = '_check_area'},
            {name = 'refill',   from = '_check_area', to = '_refill'},
            {name = 'initiate', from = '_check_area', to = '_initiate'},
            {name = 'initiate', from = '_refill', to = '_initiate'},
            {name = 'kill',     from = '_check_area', to ='_kill'}         
        },
        callbacks = {
            onenter_check_area = function(self)
                if is_etrean then  
                    self:refill()
                    self:initiate()
                    return
                end
                
                if is_eastern then
                    require("@src/features/buttons/teleports/etrean")()
                    return
                end
                
                pcall(function(...)  
                    local is_dungeon = local_player.instance:GetAttribute('Dungeon'):match('Duke')
                    if is_dungeon then
                        self:kill()
                        return
                    end
                end)
                
                if is_depths then
                    aztup.automation:set('auto_duke', not persistent_data:get('auto_duke', false))
                    getgenv().dont_auto_hop_pls = true;
                    local_player.instance:Kick('Somehow ended up in depths.')
                    return
                end
            end,
            onenter_refill = function(self)
                autoduke:refill()
                self:initiate()
            end,
            onenter_initiate = function(self)
                autoduke:create_instance()
            end,
            onenter_kill = function(self)
                autoduke:kill_duke()
            end
        }
    }),
    features = {
        "no_fall",
        "noclip",
        'no_kill_bricks',
        "mod_detector",
        "fly",
        "m1_hold",
        'auto_wisp',
        "auto_equip_weapon"
    },
    not_allowed = function()
        return false;
    end,
    character_creator_handler_used = false,
    character_creator_handler_opts = {}
})

return struct;
end;

modules["@src/automation/persistent_tasks/auto_echo_layer2"] = function()
local automation_struct = require("@src/automation/struct");
local autofarm_util = require('@src/utility/deepwoken/autofarm_utilitys');
local safety = require('@src/utility/safety');
local struct;

local auto_echo_layer2 = {
    temp_tween = function(cf, speed)
        Tween.new(cf, true, speed or 175).wait();
    end,

    server_hop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, true, true);
    end,

    player_check = function(mag, custom)
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if player == local_player.instance then continue end

            local hrp = player.Character:FindFirstChild("HumanoidRootPart");
            if not hrp then continue end

            local dist = ((custom or local_player.root_part.Position) - hrp.Position).Magnitude;
            if dist <= mag then
                return true;
            end
        end
        return false;
    end,

    send_dialogue = function(text, exit)
        local args = exit and { { exit = true } } or { { choice = text } };
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args));
        if not exit then task.wait(0.5); end
    end,
};

function auto_echo_layer2:pass_fragments()
	task.spawn(function()
		while task.wait() do
			if safety:PlayerNear(100) then
				self.server_hop();
			end
		end
	end);

	local function handleFrag()
		local tpLocation = (workspace.NPCs.Self:GetPivot() - Vector3.new(0, 15.7, 0)) * CFrame.Angles(math.rad(180), math.rad(90), math.rad(180))
		if auto_echo_layer2.player_check(200, tpLocation.Position) then
			auto_echo_layer2.server_hop()
			while task.wait() do
			end
		end
		local_player.root_part.CFrame = tpLocation;
		local slot = local_player.instance:GetAttribute("DataSlot");
		local chooseSlot = [[
                    if not game:IsLoaded() then game.Loaded:Wait(); end;
                    if game.PlaceId ~= 4111023553 then return; end
                    local slot = "%s";
                    queueonteleport('if game.PlaceId == 4111023553 then return; end; xpcall(function() local sound = Instance.new("Sound", game:GetService("CoreGui")); game:GetService("Debris"):AddItem(sound, 6); sound.Volume = 1.3; sound.SoundId = getcustomasset("Project Rain/assets/notification.mp3"); sound:Play(); end, warn);')
                    game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("WipeSlot"):InvokeServer(slot)
                    task.wait(0.5)
                ]]
		queue_on_teleport(string.format(chooseSlot, slot or "A"))
		local get_score = services.ReplicatedStorage:WaitForChild("Requests"):WaitForChild("GetScore");
		get_score.OnClientEvent:Connect(function(v)
			local wiped_at = tick();
			persistent_data:set("echoes_gained", persistent_data:get("echoes_gained", 0) + (v and typeof(v) == "table" and v.Echoes or 0))
			persistent_data:set("cycle_count", persistent_data:get("cycle_count", 0) + 1)
			persistent_data:set("wiped_at", wiped_at);
			get_score:FireServer();
		end);
		while task.wait() do
			local_player.root_part.CFrame = tpLocation;
			fireproximityprompt(workspace:WaitForChild("NPCs"):WaitForChild("Self"):WaitForChild("InteractPrompt"))
			game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({
				choice = '[The End]'
			})
		end;
	end
	task.delay(40, function()
		self.serverHop();
	end);
	local frag_handler;
	frag_handler = function()
		if not workspace.NPCs:FindFirstChild('Self') then
			require("@src/features/buttons/respawn")()
			repeat
				task.wait()
			until local_player.character and workspace.NPCs:FindFirstChild('Self')
		end
		xpcall(handleFrag, function()
			task.wait(0.1);
			frag_handler();
		end);
	end
	frag_handler();
end

function auto_echo_layer2:enter_void()
    local is_fragments = local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):match('Fragments of Self')
    if is_fragments then
        return auto_echo_layer2:pass_fragments()            
    end

    local function get_closest_kill_plane()
        local part;
        local dist = 9e9;

        for _, item in workspace:QueryDescendants("#KillPlane") do
            local current_dist = (item.Position - local_player.root_part.Position).Magnitude;

            if current_dist < dist then
                dist = current_dist;
                part = item;
            end;
        end;

        return part;
    end;

    if aztup.flags.no_kill_bricks then
        aztup_toggles.no_kill_bricks:SetValue(false);
    end;

    local start = tick();
    local plane = get_closest_kill_plane();
    repeat plane = get_closest_kill_plane(); task.wait(); until plane or tick() - start > 15;

    local playercheck = task.spawn(function()
        while task.wait() do
            if safety:PlayerNear(300) then
                self.server_hop();
            end
        end
    end);

    aztup_toggles.fly:SetValue(false);

    local tween;
    while tick() - start < 60 do
        if not plane then break; end
        if tween then tween.stop(); end;
        tween = Tween.new(plane.CFrame, false, 200);
        local_player.root_part.Velocity = Vector3.new(0, -999, 0);
        task.wait();
    end;

    pcall(task.cancel, playercheck);
    return
end

function auto_echo_layer2:get_key()
    autofarm_util:ReadyWeapon(true);

    repeat
        pcall(function()
            self.temp_tween(workspace.NPCs:FindFirstChild('TheKey'):GetPivot(), 250);
        end);
        pcall(function()
            fireproximityprompt(workspace.NPCs.TheKey.InteractPrompt);
        end);
        task.wait(0.5);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    self.send_dialogue(nil, true);

    self.temp_tween(workspace.NPCs:FindFirstChild('TheDoor'):GetPivot(), 250);

    repeat
        self.temp_tween(workspace.NPCs:FindFirstChild('TheDoor'):GetPivot(), 250);
        pcall(function()
            fireproximityprompt(workspace.NPCs:FindFirstChild('TheDoor').InteractPrompt);
        end);
        task.wait(0.5);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    self.send_dialogue(nil, true);
end

function auto_echo_layer2:spawn_keeper()
    local bonekeeper_location = CFrame.new(-5747, 459, -6357);
    self.temp_tween(bonekeeper_location, 250);
    aztup_toggles.void_mobs:SetValue(true);

    local bonekeeper = nil;
    local real_bonekeeper = nil;

    repeat
        if not bonekeeper then
            self.temp_tween(CFrame.new(-5889, 459, -6308));
        end

        if real_bonekeeper and real_bonekeeper.Parent == nil and not bonekeeper then
            bonekeeper = nil;
            real_bonekeeper = nil;
            break;
        end

        for _, v in workspace.Live:GetChildren() do
            if v == local_player.character then continue end
            if not v.Name:find(".boneboy") then continue end
            real_bonekeeper = v;
            --if not v:FindFirstChild("Target") or not v.Target.Value then continue end
            bonekeeper = v;
        end

        if not bonekeeper then
            self.temp_tween(bonekeeper_location);
        end

        task.wait();
    until bonekeeper;

    self.temp_tween(CFrame.new(-5788, 563, -6351), 250);

    repeat
        task.wait();
    until not workspace.EncounterTriggers:FindFirstChild('BonekeeperBridge')
        or (workspace.EncounterTriggers:FindFirstChild('BoneKeeperBridge') and not workspace.EncounterTriggers.BoneKeeperBridge:FindFirstChild('Barrier'));
end

function auto_echo_layer2:go_to_generator()
    self.temp_tween(CFrame.new(-5555, 529, -6475), 250);

    repeat
        self.temp_tween(CFrame.new(-5555, 529, -6475), 250);
        task.wait(0.5);
        pcall(function()
            fireproximityprompt(workspace.NPCs.TheGenerator.InteractPrompt);
        end);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    self.send_dialogue('[Restart it]');
    self.send_dialogue(nil, true);
    aztup_toggles.void_mobs:SetValue(false);
end

function auto_echo_layer2:chaser_route()
    self.temp_tween(CFrame.new(-5361, 5000, -4801), 250); -- so we dont get ragdolled and hit our head (ow) or get snow
    local foundchaser = nil;
    repeat
        self.temp_tween(CFrame.new(-5361, 285, -4801), 250);
        task.wait();

        for _, v in workspace.Live:GetChildren() do
            if v == local_player.character then continue end
            if v.Name:find('chaser') then
                foundchaser = v;
                break;
            end
        end

        self.temp_tween(CFrame.new(-5224.36523, 194.26561, -4633.03223, -0.803056717, -9.8259835e-20, -0.595902622, -3.56286109e-20, 1, -1.16878229e-19, 0.595902622, -7.26286614e-20, -0.803056717), 250);
        task.wait();
    until foundchaser;

    self.temp_tween(foundchaser:GetPivot(), 250);

    repeat
        self.temp_tween(foundchaser:GetPivot(), 250);
        pcall(function()
            fireproximityprompt(foundchaser.InteractPrompt);
        end);
        task.wait(0.5);
    until local_player.instance.PlayerGui.DialogueGui.Enabled;

    task.spawn(function() 
        while task.wait() do
            if not EffectReplicator:FindEffect("Blocking") then
                DefendActionManager.block:FireServer()
            end;
        end;
    end);

    if not EffectReplicator:FindEffect("Equipped") then
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        character_handler.Requests.DrawWeapon:FireServer(true);
    end;

    self.send_dialogue('Ethiron\'s Wake?');
    self.send_dialogue('What happened here?');
    self.send_dialogue('They mutinied?');
    self.send_dialogue('The City?');

    return foundchaser;
end

function auto_echo_layer2:void_chaser(chaser)
    aztup.flags.atb_x_offset = 0;
    aztup.flags.atb_y_offset = 0.25;
    aztup.flags.atb_z_offset = 0;
    aztup.flags.atb_prevent_voiding = true;
    aztup.flags.atb_lock_rotation = true;
    aztup_toggles.attach_to_back:SetValue(true);
    aztup.features.attach_to_back.target = chaser;
    aztup.features.attach_to_back.state = "attaching";
    aztup_toggles.mob_ai_breaker:SetValue(true);
    aztup_options.breaker_type.Value = "Aggressive";

    repeat
        task.wait();
        pcall(function()
            fireproximityprompt(chaser.InteractPrompt);
        end);
    until local_player.instance.PlayerGui.DialogueGui.Enabled or chaser.Parent == nil;

    while chaser.Parent ~= nil and task.wait() do
        if not EffectReplicator:FindEffect("Equipped") then
            local character_handler = local_player.character:FindFirstChild("CharacterHandler");
            character_handler.Requests.DrawWeapon:FireServer(true);
        end;

        if not EffectReplicator:FindEffect("Blocking") then
            DefendActionManager.block:FireServer()
        end;

        if chaser:FindFirstChild("HumanoidRootPart") and chaser:FindFirstChild("HumanoidRootPart").Position.Y > 2500 then -- we arent voiding him if we get this late
            persistent_data:set("auto_echo_layer2_wiping", true);
            server_utility:obliteration(local_player.instance:GetAttribute("DataSlot"));
            break;
        end;

        aztup.flags.atb_y_offset = (chaser:FindFirstChild("HumanoidRootPart") and chaser.HumanoidRootPart.Anchored) and 5000 or 0.75;

        --aztup.features.m1_hold.held = true;
    end

    aztup.features.m1_hold.held = false;
    aztup_toggles.mob_ai_breaker:SetValue(false);
    aztup_toggles.attach_to_back:SetValue(false);
end

local state_machine = StateMachine.create({
    initial = "idle",
    events = {
        { name = "start",        from = "idle",             to = "_check_area" },
        { name = "cc",           from = "_check_area",       to = "_create_character" },
        { name = "continuation", from = "_create_character", to = "_check_area" },
        { name = "enter_void",   from = "_check_area",       to = "_enter_void" },
        { name = "run_route",    from = "_check_area",       to = "_run_route" },
    },

    callbacks = {
        onenter_check_area = function(self)
            --if persistent_data:get("auto_echo_layer2_wiping", false) then
            --    local ok, area = pcall(function()
            --        return local_player.instance:GetAttribute("CurrentArea");
            --    end);
--
            --    if ok and area and area:match("Fragments of Self") then
            --        auto_echo_layer2:pass_fragments();
            --    end
--
            --    local character_creator = workspace:WaitForChild('CharacterCreator', 30);
            --    persistent_data:set("auto_echo_layer2_wiping", false);
--
            --    if character_creator and local_player.character and local_player.character.Parent == character_creator then
            --        self:cc();
            --        return;
            --    end
            --end

            local requests = services.ReplicatedStorage:WaitForChild("Requests");
            local start = requests:WaitForChild("StartMenu"):WaitForChild("Start")
            repeat
                start:FireServer()
                task.wait(0.5)
            until local_player.character;
            local is_character_creation = workspace:FindFirstChild('CharacterCreator') and local_player.character.Parent == workspace.CharacterCreator

            if is_character_creation then
                self:cc();
                return;
            end

            local ok, dungeon = pcall(function()
                return local_player.instance:GetAttribute('Dungeon');
            end);

            if ok and dungeon and dungeon:match('Layer2Floor1') then
                self:run_route();
                return;
            end

            repeat task.wait() until local_player.instance:GetAttribute('CurrentArea');
            self:enter_void();
        end,

        onenter_create_character = function(self)
            struct:create_character();
            self:continuation();
        end,

        onenter_enter_void = function(self)
            auto_echo_layer2:enter_void();
        end,

        onenter_run_route = function(self)
            auto_echo_layer2:get_key();
            auto_echo_layer2:spawn_keeper();
            auto_echo_layer2:go_to_generator();
            local chaser = auto_echo_layer2:chaser_route();
            auto_echo_layer2:void_chaser(chaser);

            task.wait(5);
            persistent_data:set("auto_echo_layer2_wiping", true);
            server_utility:obliteration(local_player.instance:GetAttribute("DataSlot"));
        end,
    }
});

struct = automation_struct:construct({
    persistent_data_store = "auto_echo_layer2_store",
    persistent_data_flag  = "auto_echo_layer2",
    id = "auto_echo_layer2",
    state_machine = state_machine,

    features = {
        "no_fall",
        "noclip",
        "fly",
        "no_kill_bricks",
        "m1_hold",
        "auto_equip_weapon",
    },

    character_creator_handler_used = true,
    character_creator_handler_opts = {
        origin = "DiluvianMechanism",
        modifiers = {
            "All"
        },
    },
    on_run = function()
        local Converted = {
            ["_ScreenGui"] = Instance.new("ScreenGui");
            ["_Frame"] = Instance.new("Frame");
            ["_UICorner"] = Instance.new("UICorner");
            ["_UISizeConstraint"] = Instance.new("UISizeConstraint");
            ["_Frame1"] = Instance.new("Frame");
            ["_UICorner1"] = Instance.new("UICorner");
            ["_Objects"] = Instance.new("Frame");
            ["_UIListLayout"] = Instance.new("UIListLayout");
            ["_title"] = Instance.new("TextLabel");
            ["_UIGradient"] = Instance.new("UIGradient");
            ["_Frame2"] = Instance.new("Frame");
            ["_echo_count"] = Instance.new("TextLabel");
            ["_time"] = Instance.new("TextLabel");
            ["_echoes_a_min"] = Instance.new("TextLabel");
            ["_cycles"] = Instance.new("TextLabel");
            ["_stage"] = Instance.new("TextLabel");
            ["_ui notes"] = Instance.new("ModuleScript");
        }

        Converted["_ScreenGui"].ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        Converted["_ScreenGui"].Parent = game:GetService("CoreGui")
        Converted["_ScreenGui"].ScreenInsets = Enum.ScreenInsets.None;
        Converted["_ScreenGui"].OnTopOfCoreBlur = true;

        Converted["_Frame"].AnchorPoint = Vector2.new(1, 0)
