                    }
                }
                game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("Craft"):InvokeServer(unpack(args))
            end)
            task.wait(1)
        elseif has_rock and has_coal then
            task.spawn(function()
                local args = {
                    {
