aztup.maid:give_task(workspace.DescendantAdded:Connect(LPH_NO_VIRTUALIZE(function(projectile)
	if not (aztup and aztup.flags and aztup.flags.auto_parry) then
		return
	end

	local allowed_targets = aztup_options.allowed_targets.Value
	if not allowed_targets.PVE and not allowed_targets.All then
		return
	end

	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end
	
	if projectile.Name == "REP_SOUND_1590181673" and projectile:FindFirstAncestorWhichIsA("Model").Name == "MetalTurret" then
		
		
		local closest_player
		local closest_distance = math.huge
		for _, char in workspace:WaitForChild("Live"):GetChildren() do
			if char and char:FindFirstChild("HumanoidRootPart") then
				local distance = (projectile.Parent.Position - char.HumanoidRootPart.Position).Magnitude
				if distance < closest_distance then
					closest_distance = distance
					closest_player = char
				end
			end
		end
		local pos_delta = (projectile.Parent.Position - local_player.root_part.Position)
		
		if
			not (
				math.abs(pos_delta.X) < 10
				and math.abs(pos_delta.Y) < 15
				and math.abs(pos_delta.Z) < 50
			)
		then
			return		
end;
		if closest_distance > 120 or not services.Players:GetPlayerFromCharacter(closest_player) or not services.Players:GetPlayerFromCharacter(closest_player).Backpack:FindFirstChild("Mantra:TurretMetal{{Metal Turret}}") then
			return
		end

		if closest_player == local_player.character then return end

		DefendActionManager:queue_generic_dodge_task(closest_player)
	elseif projectile.Name == "ParticleEmitter3" and string.find(projectile:GetFullName(), "avatar") then
		local sdelay = (Latency:get_ping() / 2)
		task.wait(0.75 - sdelay)

		local avatar = projectile.Parent.Parent.Parent
		local target = avatar and avatar:FindFirstChild("Target")

		if target and target.Value ~= local_player.character then
			return
		end

		repeat
			general:generic_parry_ap_task(avatar)
			task.wait(0.15 - (Latency:get_ping() / 2))
		until not projectile.Parent or not projectile.Enabled
	elseif projectile.Name == "GrabPart" then
		repeat
			task.wait()
		until not projectile.Parent or (projectile.Position - local_player.root_part.Position).Magnitude < 20
		if not projectile.Parent then
			return
		end

		local ethiron
		for _, entity in workspace:WaitForChild("Live"):GetChildren() do
			if entity.Name:match("avatar") then
				ethiron = entity
				break
			end
		end

		DefendActionManager:queue_generic_dodge_task(ethiron)
	elseif projectile.Name == "SpikeStabEff" then
		local chaser
		for _, entity in live:GetChildren() do
			if not entity.Name:match(".chaser") then
				continue
			end
			chaser = entity
			break
		end

		if not chaser then
			return
		end

		BlockInputManager:add_task("SpikeStabEff", chaser, nil, 2000):debris(0.6)
		run_af()
		task.wait(0.6 - Latency:get_ping())
		run_af()
		if (projectile.Position - local_player.root_part.Position).Magnitude > 20 then
			return
		end

		if aztup.flags.auto_parry_debug then
			Library:Notify("[SpikeStabEff] Performing action 1: Parry")
		end
		DefendActionManager:queue_generic_parry_task(chaser)
	elseif projectile.Name == "HitTendril" then
		local chaser
		for _, entity in live:GetChildren() do
			if not entity.Name:match(".chaser") then
				continue
			end
			chaser = entity
			break
		end

		if not chaser then
			return
		end

		local hrp = chaser:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return
		end

		local hasTelegraph = projectile.Parent == hrp or hrp:FindFirstChild("TelegraphAttach") ~= nil

		if hasTelegraph then
			run_af()
			task.wait(0.585 - Latency:get_ping())
			run_af()
			if aztup.flags.auto_parry_debug then
				Library:Notify("[HitTendril] Performing action 1: Dodge")
			end
			DefendActionManager:queue_generic_dodge_task(chaser)
		else
			run_af()
			task.wait(0.600 - Latency:get_ping())
			run_af()

			if aztup.flags.auto_parry_debug then
				Library:Notify("[HitTendril] Performing action 1: Parry")
			end
			DefendActionManager:queue_generic_parry_task(chaser)
		end
	end
end)))

return nil
end;

modules["@src/features/auto-parry/block-input-manager"] = function()
local BlockInputManagerClass = {};
function BlockInputManagerClass.new()
    local self = setmetatable({}, {
        __index = BlockInputManagerClass
    });
    self.tasks = {};

    function self:add_task(name, mob, box_func, range)
        local block_input = aztup.flags.block_input;
        if not block_input then return {debris=function()end,remove=function()end}end;

        local allowed_targets = aztup_options.allowed_bi_targets.Value;

        if mob.Name:sub(1, 1) == "." and not allowed_targets.PVE then
            return {debris=function()end,remove=function()end}        
end;

        if mob.Name:sub(1, 1) ~= "." and not allowed_targets.PVP then
            return {debris=function()end,remove=function()end}        
end;

        if not local_player.root_part or not mob:FindFirstChild("HumanoidRootPart") then
            return {debris=function()end,remove=function()end}        
end; 

        local id = services.HttpService:GenerateGUID(false);
        self.tasks[id] = {
            name = name,
            mob = mob,
            range = range,
            in_hitbox = box_func
        };

        return {
            removed = false,
            remove = function()
                
                
                
                
        
                self.removed = true;
                self.tasks[id] = nil;
            end,
            debris = function(time, time2)
                task.delay(typeof(time) == "table" and time2 - Latency:half_ping() or time - Latency:half_ping(), function()
                    
                    
                    
                    
                    
                    self.tasks[id] = nil;
                end);
            end
        }
    end

    LPH_NO_VIRTUALIZE(function()
        function self:should_block_input()
            local should_block = false;
            for index, task in self.tasks do
                if not task.mob or not task.mob.Parent then
                    self.tasks[index] = nil;
                end;
            
                if task.mob then
                    local mob_root = task.mob:FindFirstChild("HumanoidRootPart");
                    if not mob_root then continue end
                
                    local distance = (local_player.root_part.Position - mob_root.Position).Magnitude;
                    if task.range and distance > task.range or task.in_hitbox and not task.in_hitbox() then continue end
                
                    if not should_block then
                        local block_input = aztup.flags.block_input;
                        if not block_input then return {debris=function()end,remove=function()end}end;
                        
                        local allowed_targets = aztup_options.allowed_bi_targets.Value;
                        should_block = allowed_targets.PVE and task.mob.Name:sub(1, 1) == "." or allowed_targets.PVP
                    end;
                end;
            end;

            return should_block        
end;
    end)();

    return self
end


getgenv().BlockInputManager = BlockInputManagerClass.new();
return getgenv().BlockInputManager
end;

modules["@src/features/auto-parry/data/action"] = function()
local signal = require("@src/utility/signal")

local actionCreator = {} do
    function actionCreator.new(opts)
        opts = opts or {}

        local self
        self = setmetatable({}, {
            __index = actionCreator,
            __newindex = function(_, k, v)
                if k == "actions" or k == "pending_action" or k == "signal" or k == "_signal_enabled" or k == "cancelled" then
                    rawset(self, k, v)
                    return
                elseif k == "when_ms" then
                    rawset(self, "when", v / 1000);
                    return                
end
                self.pending_action[k] = v
            end
        })

        self.actions = {}
        self.pending_action = {}
        self.signal = signal.new()
        self._signal_enabled = opts.signal == true
        self.cancelled = false;

        return self
    end

    function actionCreator:enable_signal(b)
        self._signal_enabled = b == true
        return self
    end

    function actionCreator:get_signal()
        return self.signal
    end

    
    function actionCreator:play()
        local id = #self.actions + 1
        self.actions[id] = self.pending_action
        self.pending_action = {}

        if self._signal_enabled then
            self:get_signal():fire(id)
        end

        return self
    end

    
    function actionCreator:push()
        table.insert(self.actions, self.pending_action)
        self.pending_action = {}
        return self
    end

    function actionCreator:get()
        return self.actions
    end
end

return actionCreator
end;

modules["@src/features/auto-parry/data/apc_fallback"] = function()
--[[
    apc_fallback.lua

    Generic per-weapon-type Auto Parry timing, ported from APC (Lycoris Rewrite)'s
    WeaponTest.lua windup formulas.

    Project Rain's own data/base.lua only covers named, per-exact-animation-ID moves
    (mantras, spells, bosses - 129 hardcoded entries). Ordinary weapon M1 swings aren't
    in there at all (that table was the "Timings" data Rain stripped from the OSS
    release). This module is what actually "imports APC timings into Project Rain":
    when animator-handler.lua can't find an exact-ID match, it calls apc_fallback.build()
    instead of giving up, and gets back a normal PR timing-data table (with a `run`
    function) built from APC's live track.Speed + weapon.type formulas.

    Ported 1:1 from APC's WeaponTest.lua where the formula is a plain function of
    (track.Speed, weapon.ss). Not ported (on purpose, see README/notes to the user):
      - APC's own hitbox/prediction/blockfollow tuning (timing.pbfb, timing.htype,
        timing.pfht, etc.) - those are knobs on APC's *own* defender engine and have
        no equivalent field on PR's action/hitbox contract.
      - The busy-wait sub-branches (Pistol "Shot", Rifle "2", Bow spark-wait) that block
        on task.wait() until track.Speed changes or a part appears. PR calls `data.run`
        synchronously off the animation-played hot path with a task concurrency limiter;
        blocking there for multiple frames per enemy is a real stall risk, so those
        variants fall back to the plain per-type formula instead of the exact sub-case.
      - The Evengarde / Titus boss-specific special-cased loops (self:action spam,
        M1-windup-only-once-per-4s guards) - narrow boss workarounds, not general timings.
    All of the above are individually portable later if they turn out to matter; they
    were deliberately left out for now since "other stuff is less important" per the
    brief - this file is only the generic per-weapon windup.
]]

local weapon = require("@src/features/auto-parry/data/weapon");

local apc_fallback = {};

-- entity: the Character whose weapon/track we're evaluating.
-- Returns a PR-shaped timing `data` table (see data/base.lua for the shape), or nil if
-- APC has no formula for this entity's current weapon (no weapon equipped, or a type
-- APC itself doesn't cover, e.g. thrown/unarmed edge cases).
function apc_fallback.build(entity)
    local w = weapon.data(entity);
    if not w or not w.type then
        return nil;
    end;

    return {
        source = "apc_fallback",
        action_type = "M1",
        name = "APC " .. w.type,
        run = function(action)
            -- `track` and `weapon` are injected as globals by animator-handler.lua's
            -- setfenv before this runs, same as every other data.run entry in base.lua.
            local w = weapon or {};
            local speed = track.Speed;
            if not speed or speed == 0 then
                return;
            end;

            local windup;
            if w.type == "Greataxe" and speed ~= 1.0 then
                windup = (0.171 / speed) + 0.120;
            elseif w.type == "Greataxe" then
                windup = (0.171 / speed) + (0.250 / (w.ss or 1));
            elseif w.type == "Greathammer" and speed ~= 1.0 then
                windup = (0.150 / speed) + 0.200;
            elseif w.type == "Greathammer" then
                windup = (0.150 / speed) + (0.250 / (w.ss or 1));
            elseif w.type == "Greatcannon" and speed ~= 1.0 then
                windup = (0.155 / speed) + 0.160;
            elseif w.type == "Greatcannon" then
                windup = (0.155 / speed) + 0.300;
            elseif w.type == "Rapier" then
                windup = (0.155 / speed) + 0.120;
            elseif w.type == "Rifle" then
                windup = (0.174 / speed) + 0.125;
            elseif w.type == "Club" then
                windup = (0.180 / speed) + 0.100;
            elseif w.type == "Twinblade" then
                windup = (0.200 / speed) + 0.050;
            elseif w.type == "Spear" then
                windup = (0.150 / speed) + 0.100;
            elseif w.type == "Greatsword" then
                windup = (0.158 / speed) + 0.150;
            elseif w.type == "Fist" then
                windup = (0.140 / speed) + 0.130;
            elseif w.type == "Dagger" then
                windup = (0.200 / speed) + 0.075;
            elseif w.type == "Staff" then
                windup = 0.350;
            elseif w.type == "Sword" then
                windup = (0.200 / speed) + 0.100;
            elseif w.type == "Bow" then
                windup = 0.1;
            elseif w.type == "Pistol" then
                windup = 0.350 / (w.ss or 1);
            end;

            if not windup or windup ~= windup or windup == math.huge then
                return;
            end;

            local length = w.length or 4;
            action.when = windup;
            action.type = "Parry";
            action.hitbox = Vector3.new(length * 2.1, length * 2.1, length * 2.1);
            action:push();
        end,
    };
end

return apc_fallback;
end;

