function autofarm_utilities:Tween(location: CFrame | Vector3 | BasePart, speed: number?, ping_based: boolean?)
    local loc_type = type(location)
    if loc_type == 'Vector3' then
        location = CFrame.new(location)
    elseif loc_type == 'BasePart' then
        location = location:GetPivot()
    end

    Tween.new(location, ping_based or true, speed or 250).wait()
end

function autofarm_utilities:NeedFood(percent): boolean
    if not percent then percent = 0.25; end
    
    local water = local_player.character:FindFirstChild('Water')
    local stomach = local_player.character:FindFirstChild('Stomach')
    return (water.Value <= (water.MaxValue * percent)) or (stomach.Value <= (stomach.MaxValue * percent))
end

function autofarm_utilities:RefillFood()
    if is_eastern then

    elseif is_etrean then
        
    end
end

function autofarm_utilities:HealthCheck(percent): boolean
    return local_player.humanoid and local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * percent)
end

function autofarm_utilities:GetClosestMob(name, max_magnitude): Model
    local closest: Model = nil
    
    for _, mob: Model in workspace.Live:GetChildren() do
        if not mob:IsA('Model') then continue end
        if name and not mob.Name:find(name) then continue end
        if services.Players:GetPlayerFromCharacter(mob) then continue end
        
        if not closest then
            local dist = (local_player.root_part.Position - mob:GetPivot().Position).Magnitude
            if max_magnitude and dist > max_magnitude then continue end
            closest = mob
            continue
        end
        
        if closest then
            local mobDist = (local_player.root_part.Position - mob:GetPivot().Position).Magnitude
            local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
            
            if mobDist < closestDist then
                closest = mob
            end
        end
    end
    
    return nil
end

function autofarm_utilities:GetClosestNPC(name: string, wait: boolean): Model
    local function closest_npc()
        local closest: Model = nil
        
        for _, npc: Model in workspace.NPCs:GetChildren() do
            if not npc.Name:match(name) then continue end
            
            if not closest then
                closest = npc
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                local npcDist = (local_player.root_part.Position - npc:GetPivot().Position).Magnitude
                
                if closestDist > npcDist then
                    closest = npc
                end
            end
        end
        
        return closest
    end
    
    local closest = closest_npc()
    
    if wait and not closest then
        repeat closest = closest_npc(); task.wait(); until closest
    end
    
    return closest
end 

function autofarm_utilities:GetClosestCampfire(backup_location: CFrame, wait: boolean): Model
    local function closest_campfire(): Model
        local closest: Model = nil
        
        for _, campfire: Model in workspace.Thrown:GetChildren() do
            if not campfire.Name:match('Campfire') then continue end
            
            if not closest then
                closest = campfire
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                local campfireDist = (local_player.root_part.Position - campfire:GetPivot().Position).Magnitude
                
                if closestDist > campfireDist then
                    closest = campfire
                end
            end
        end
        
        return closest
    end
    
    local closest = closest_campfire()
    
    if not closest and backup_location then
        Tween.new(backup_location, true, 250).wait()
        closest = closest_campfire()
        
        if wait and not closest then
            repeat closest = closest_campfire(); task.wait(); until closest
        end
    end
    
    return closest
end

function autofarm_utilities:GetClosestWell(backup_location: CFrame, wait: boolean): Model
    local function closest_well(): Model
        local closest: Model = nil
        
        for _, well: Model in workspace.Map:GetChildren() do
            if not well.Name:match('Well') then continue end
            
            if closest == nil then
                closest = well
                continue
            end
            
            local closestdist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
            local dist        = (local_player.root_part.Position - well:GetPivot().Position).Magnitude
            
            if dist < closestdist then
                closest = well
            end
        end
        
        return closest
    end
    
    local closest: Model = closest_well()
    
    if not closest and backup_location then
        Tween.new(backup_location, true, 250).wait()
        closest = closest_well()
        
        if wait and not closest then
            repeat closest = closest_well(); task.wait(); until closest
        end
    end
    
    return closest
end

function autofarm_utilities:GetClosestChest(wait: boolean, max_distance: number): Model    
    local function search()
        local closest: Model = nil
        
        for _, chest: Model in workspace.Thrown:GetChildren() do
            if chest:HasTag('looted') then continue end
            if not chest:FindFirstChild('Lid') then continue end
            
            if not closest then
                local dist = (local_player.root_part.Position - chest:GetPivot().Position).Magnitude
                if max_distance and dist > max_distance then continue end
                closest = chest
                continue
            end
            
            if closest then
                local chestDist = (local_player.root_part.Position - chest:GetPivot().Position).Magnitude
                local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                
                if chestDist < closestDist then
                    closest = chest
                end
            end
        end
        
        return closest
    end
    
    local closest: Model = search()
    
    if wait and not closest then
        repeat search(); task.wait(); until closest
    end
    
    return closest
end


function autofarm_utilities:GrabChest(struct, using_mob_breaker: boolean, wait_time: number, max_distance: number)
    local closest: Model = self:GetClosestChest(true, max_distance or nil)
    if not closest then return end
    
    closest:AddTag('looted')
    
    if using_mob_breaker then
        pcall(function(...)  
            struct.active_features['mob_ai_breaker'].current_connection:Disconnect()
            struct.active_features['mob_ai_breaker']:disable()
        end)
    end
    
    local time_waited = tick()
    
    repeat
        pcall(function(...)  
            Tween.new(closest:GetPivot(), true, 250).wait()
        end)
        
        if not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') then
            pcall(function(...)  
                fireproximityprompt(closest.InteractPrompt)
            end)
        end
        
        task.wait(0.2)
    until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or ((tick() - time_waited) > (10))
    
    time_waited = tick()
    
    repeat task.wait() until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or ((tick() - time_waited) > (wait_time or 3))
    if local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') then
        pcall(function(...)  
            local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt'):FindFirstChild('Choice'):FireServer('EXIT')
        end)
    end
end


function autofarm_utilities:GrabChests(struct, using_mod_breaker: boolean, wait_time: number, max_distance: number)
    local chest = self:GetClosestChest(false, max_distance or nil)
    repeat
        local dist = (local_player.root_part.Position - chest:GetPivot().Position).Magnitude
        if max_distance and dist > max_distance then continue end
        
        local time_waited = tick()
        
        repeat
            pcall(function(...)  
                Tween.new(chest:GetPivot(), true, 250).wait()
            end)
            
            if not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') then
                pcall(function(...)  
                    fireproximityprompt(chest.InteractPrompt)
                end)
            end
            
            task.wait(0.2)
        until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or ((tick() - time_waited) > (10))
        
        time_waited = tick()
        
        repeat task.wait() until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or ((tick() - time_waited) > (wait_time or 3))
        if local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') then
            pcall(function(...)  
                local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt'):FindFirstChild('Choice'):FireServer('EXIT')
            end)
        end
        
        chest = self:GetClosestChest(false, max_distance or nil)
        task.wait()
    until not chest
end

return autofarm_utilities
end;

modules["@src/utility/deepwoken/deepwoken_builder_api"] = function()
local url_encoding = require("@src/utility/urlencoding");


local deepwoken_builder_api = {} do
    deepwoken_builder_api.__index = deepwoken_builder_api

    function deepwoken_builder_api:request_build(url)
        local build_id = url:match("id=([%w]+)")
        if not build_id then
            return false, "bad id"        
end
        return request({
            Url = "https://deepwoken.co/api/proxy?url=" .. url_encoding.encode(string.format("https://api.deepwoken.co/build?id=%s&options={}", build_id)),
            Method = "GET",
            Headers = {
                ["Content-Type"] = "application/x-www-form-urlencoded"
            },
            Body = "url=" .. url_encoding.encode(url)
        }).Body
    end;

    function deepwoken_builder_api:get_general_data()
        return request({
            Url = "https://deepwoken.co/api/proxy?url=https%3A%2F%2Fapi.deepwoken.co%2Fget%3Ftype%3Dall&options=%7B%22signal%22%3A%7B%7D%7D",
            Method = "GET",
            Headers = {
                ["Content-Type"] = "application/x-www-form-urlencoded"
            },
        }).Body
    end;
end;

return deepwoken_builder_api
end;

modules["@src/utility/deepwoken/effect_replicator_handler"] = function()






if not getloadedmodules then
    return game:GetService(STR_TBL_SF_INVOKE("Players")).LocalPlayer:Kick(STR_TBL_SF_INVOKE("Executor is unsupported. [missing getloadedmodules, effect_replicator_handler]"))
end;


local Maid = require("@src/utility/maid");
local EffectReplicatorHandler = {};
EffectReplicatorHandler.__index = EffectReplicatorHandler;
EffectReplicatorHandler.hooks = {};
EffectReplicatorHandler.maid = Maid.new();

function EffectReplicatorHandler:hook(type, func)
    local hook = {};
    function hook:remove()
        table.remove(EffectReplicatorHandler.hooks, self.index);
    end; 

    hook.type = type;
    hook.call = func;
    hook.index = table.insert(EffectReplicatorHandler.hooks, hook);

    return hook
end;

function EffectReplicatorHandler:connect()
    self.maid:do_cleaning();

    local RawEffectReplicator = game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator");
    if not table.find(getloadedmodules(), RawEffectReplicator) then
        repeat task.wait(0.06) warn("getloadedmodules might be failing!") until table.find(getloadedmodules(), RawEffectReplicator);
    end;
    local EffectReplicator = base_require(game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator"));
    getgenv().EffectReplicator = EffectReplicator;

    self.maid:give_task(EffectReplicator.EffectAdded:Connect(function(effect)
        setthreadidentity(8);
        for _, hook in pairs(EffectReplicatorHandler.hooks) do
            if hook.type == "added" and hook.call then
                task.spawn(xpcall, function()
                    hook.call(effect);
                end, function(err)
                    Logger.error(string.format("effectreplicator added hook: %s", err));
                end);
            end;
        end;
    end));
    
    self.maid:give_task(EffectReplicator.EffectRemoved:Connect(function(effect)
        for _, hook in pairs(EffectReplicatorHandler.hooks) do
            if hook.type == "removed" then
                xpcall(function()
                    hook.call(effect);
                end, function(err) 
                    Logger.error(string.format("effectreplicator removed hook: %s", err));
                end);
            end;
        end;  
    end));
end;

task.spawn(pcall, function()
    while not pcall(function() aztup.maid:give_task(EffectReplicatorHandler.maid); end) do task.wait() end;
end);

task.spawn(pcall, function()
    local update = game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("EffectReplication"):WaitForChild("_update");
    update.OnClientEvent:Connect(function(effect)
        if effect.updateType == "clear" or effect.updateType == "updatecontainer" then
            EffectReplicatorHandler:connect();  
        end;
    end);

    EffectReplicatorHandler:connect();
end);
return EffectReplicatorHandler
end;

modules["@src/utility/deepwoken/general_utilitys"] = function()


local general = {}; 
local collision_utils = base_require(game:GetService("ReplicatedStorage"):WaitForChild("Modules"):WaitForChild("CollisionUtils"));
general.collision_utils = collision_utils;

function general:in_air()
    local sensor = local_player.root_part:FindFirstChild("GroundSensor");
    if EffectReplicator:HasEffect("Swimming") then
        return false    
elseif EffectReplicator:HasEffect("AirBorne") then
        return true    
elseif sensor and not sensor.SensedPart then
        if not collision_utils.solidParams then return false end
        return not collision_utils:Raycast(local_player.root_part.Position, Vector3.new(0, -(sensor.SearchDistance + 3), 0), collision_utils.solidParams)    
end

    return false
end;

function general:get_highest_point(x: number, z: number)
    local filter = {};
    local live = workspace:FindFirstChild("Live");
    local npcs = workspace:FindFirstChild("NPCs");
    if live then table.insert(filter, live); end
    if npcs then table.insert(filter, npcs); end

    local params = RaycastParams.new()
    params.FilterDescendantsInstances = filter
    params.FilterType = Enum.RaycastFilterType.Blacklist

    local floor = workspace:Raycast(Vector3.new(x, 5000, z), Vector3.new(0, -10000, 0), params);
    if floor and floor.Instance then
        return floor.Position.Y + 1.3    
end;

    local holder_sea = workspace:FindFirstChild("HolderSea", true);
    if holder_sea then
        return holder_sea.Position.Y + 1.3    
end;

    return 50000
end;

function general:is_teammate(player)
    local myGuild = local_player.instance:GetAttribute('Guild') or '';
    local playerGuild = player:GetAttribute('Guild') or '';
    if myGuild == '' then return end

    return myGuild == playerGuild
end;

local current_boxes = {};

local function trim_boxes()
    local max_boxes = (aztup and aztup.flags and aztup.flags.max_boxes) or 0
    if max_boxes <= 0 then return end
    while #current_boxes > max_boxes do
        local pair = table.remove(current_boxes, 1)
        if pair then
            for _, part in pair do
                if part and part.Parent then
                    part:Destroy()
                end
            end
        end
    end
end
local function draw_hitbox(hitbox: Vector3, root_pos: CFrame, enemy_pos: CFrame, offset: CFrame, is_ball: boolean?, ok: boolean, too_far: boolean, hidden: boolean?, hit_color: Color3?, miss_color: Color3?)
    local camera: Camera = workspace.CurrentCamera or {Position = Vector3.zero};
    if (enemy_pos.Position - camera.CFrame.Position).Magnitude > 300 then
        return
    end

    trim_boxes()

    local fake_root = nil
    if ok then
        fake_root = Instance.new("Part")
        fake_root.Size = Vector3.new(2, 2, 1)
        fake_root.CFrame = root_pos
        fake_root.Anchored = true
        fake_root.CanCollide = false
        fake_root.Material = Enum.Material.ForceField
        fake_root.CastShadow = false
    end

    local hitbox_part = Instance.new("Part")
    hitbox_part.Size = hitbox
    hitbox_part.CFrame = enemy_pos * (offset or CFrame.new())
    hitbox_part.Anchored = true
    hitbox_part.CanCollide = false
    hitbox_part.Material = Enum.Material.ForceField
    hitbox_part.Shape = is_ball and Enum.PartType.Ball or Enum.PartType.Block
    hitbox_part.CastShadow = false

    if fake_root then
        table.insert(current_boxes, { hitbox_part, fake_root })
    else
        table.insert(current_boxes, { hitbox_part })
    end

    local trans = 1 - (((aztup and aztup.flags and aztup.flags.hb_trans) or 0) / 100)
    hitbox_part.Transparency = trans
    if fake_root then
        fake_root.Transparency = trans
    end

    hitbox_part.Parent = workspace
    if fake_root then
        fake_root.Parent = workspace
    end

    local lifetime = (hidden or not aztup.flags.view_hitboxes or too_far) and 0 or 1
    services.Debris:AddItem(hitbox_part, lifetime)
    if fake_root then
        services.Debris:AddItem(fake_root, lifetime)
    end

    hitbox_part.Color = ok and (hit_color or Color3.new(0, 1, 0)) or (miss_color or Color3.new(1, 0, 0))
    if fake_root then
        fake_root.Color = hit_color or Color3.new(0, 1, 0)
    end

    if hidden or not aztup.flags.view_hitboxes or too_far then
        hitbox_part.Transparency = 1
        if fake_root then
            fake_root.Transparency = 1
        end
    else
        services.TweenService:Create(hitbox_part, TweenInfo.new(1), { Transparency = 1 }):Play()
        if fake_root then
            services.TweenService:Create(fake_root, TweenInfo.new(1), { Transparency = 1 }):Play()
        end
    end
end

function general:in_hitbox_with_pos(root_pos: CFrame, enemy_pos: CFrame, hitbox: Vector3, offset: CFrame, hidden: boolean?, is_ball: boolean?, hit_color: Color3?, miss_color: Color3?)  
    local too_far = false
    if local_player and local_player.root_part then
        too_far = (root_pos.Position - local_player.root_part.Position).Magnitude > 200
    end

    if (root_pos.Position - local_player.root_part.Position).Magnitude > (200 + (hitbox.Magnitude * 2)) then
        return false
    end

    local ok = false
    if is_ball then
        local probe = Instance.new("Part")
        probe.Size = hitbox
        probe.CFrame = enemy_pos * (offset or CFrame.new())
        probe.Anchored = true
        probe.Shape = Enum.PartType.Ball
        probe.CanCollide = false
        probe.Transparency = 1
        probe.CanQuery = true
        probe.Parent = workspace

        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Include
        overlap.FilterDescendantsInstances = { 
            (function()
                local pr = Instance.new("Part")
                pr.Size = Vector3.new(2, 2, 1)
                pr.CFrame = root_pos
                pr.Anchored = true
                pr.CanCollide = false
                pr.Transparency = 1
                pr.CanQuery = true
                pr.Parent = workspace
                return pr
            end)()
        }

        local parts = services.Workspace:GetPartsInPart(probe, overlap)
        ok = #parts > 0

        
        for _, inst in overlap.FilterDescendantsInstances do
            inst:Destroy()
        end
        probe:Destroy()
    else

        local root_probe = Instance.new("Part")
        root_probe.Size = Vector3.new(2, 2, 1)
        root_probe.CFrame = root_pos
        root_probe.Anchored = true
        root_probe.CanCollide = false
        root_probe.Transparency = 1
        root_probe.CanQuery = true
        root_probe.Parent = workspace

        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Include
        overlap.FilterDescendantsInstances = { root_probe }

        local parts = services.Workspace:GetPartBoundsInBox(enemy_pos * (offset or CFrame.new()), hitbox, overlap)
        ok = #parts > 0

        services.Debris:AddItem(root_probe, 0);
    end

    
    if aztup and aztup.flags and aztup.flags.view_hitboxes and not hidden and not too_far then
        draw_hitbox(hitbox, root_pos, enemy_pos, offset, is_ball, ok, too_far, hidden, hit_color, miss_color)
    end

    return ok
end
function general:in_hitbox(
    a: any,
    b: any,
    c: any,
    d: any,
    e: any?,
    f: any?
)
    
    
    
    
    

    local hitbox: Vector3
    local offset: CFrame
    local root_pos: CFrame
    local enemy_pos: CFrame
    local hidden: boolean?
    local is_ball: boolean? 

    if typeof(a) == "Vector3" and typeof(b) == "CFrame" then
        
        hitbox = a
        offset = b
        root_pos = c
        enemy_pos = d
        hidden = e
        is_ball = f
    else
        
        root_pos = a
        enemy_pos = b
        hitbox = c
        offset = d
        local show = e

        
        
        hidden = (show == false)
        is_ball = nil
    end

    return self:in_hitbox_with_pos(root_pos, enemy_pos, hitbox, offset, hidden, is_ball)
end;

function general:is_ap_anim(id)
    local data;
    for _, timing in timings do
        if timing.ids and table.find(timing.ids, tostring(id:match("%d+"))) then
            data = timing;
        end;
    end;   

    return data ~= nil
end;

function general:playing_ap_anims(entity, ids)
    for _, track in entity.Humanoid:GetPlayingAnimationTracks() do
        if ids then
            if table.find(ids, track.Animation.AnimationId) then
                continue            
end;
        end

        local data;
        for _, timing in timings do
            if timing.ids and table.find(timing.ids, tostring(track.Animation.AnimationId:match("%d+"))) then
                data = timing;
            end;
        end;   
        
        if data then
            return true        
end;
    end;

    return false
end;

