modules["@src/utility/librarys/components/slider"] = function()


return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local RenderStepped = context.RenderStepped
	local TweenService = game:GetService('TweenService')

	local Component = {}

	local function createRounder(rounding)
		return function(value)
			if rounding == 0 then
				return math.floor(value)
			end
			return tonumber(string.format('%.' .. tostring(rounding) .. 'f', value))
		end
	end

	local function createSizeTweener()
		local activeTween

		return function(frame, size)
			if frame.Size == size then
				return
			end

			if activeTween then
				activeTween:Cancel()
				activeTween = nil
			end

			local tween = TweenService:Create(frame, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Size = size;
			}) 
			activeTween = tween
			tween.Completed:Connect(function()
				if activeTween == tween then
					activeTween = nil
				end
			end)
			tween:Play()
		end
	end

	function Component.AddSlider(self, Idx, Info)
		assert(Info.Default ~= nil, 'AddSlider: Missing default value.')
		assert(Info.Text,    'AddSlider: Missing slider text.')
		assert(Info.Min ~= nil,     'AddSlider: Missing minimum value.')
		assert(Info.Max ~= nil,     'AddSlider: Missing maximum value.')
		assert(Info.Rounding ~= nil, 'AddSlider: Missing rounding value.')

		local Slider = {
			Value    = Info.Default;
			Min      = Info.Min;
			Max      = Info.Max;
			Rounding = Info.Rounding;
			MaxSize  = 232;
			Type     = 'Slider';

			Text     = Info.Text;
			Prefix   = type(Info.Prefix) == "string" and Info.Prefix or "";
			Suffix   = type(Info.Suffix) == "string" and Info.Suffix or "";

			Visible  = (type(Info.Visible)  == "boolean") and Info.Visible  or true;
			Disabled = (type(Info.Disabled) == "boolean") and Info.Disabled or false;

			Callback = Info.Callback or function(_) end;
			Changed  = Info.Changed  or function(_) end;
			Compact  = not not Info.Compact;
			HideMax  = not not Info.HideMax;
			Tooltip  = Info.Tooltip;
		}

		if self.Objects then
			table.insert(self.Objects, {
				internal_name = Idx, settings = Info, Type = "Slider"
			})
		end

		local Groupbox  = self
		local Container = Groupbox.Container

		if not Slider.Compact then
			Library:CreateLabel({
				Size = UDim2.new(1, 0, 0, 10);
				TextSize = 14;
				Text = Slider.Text;
				TextXAlignment = Enum.TextXAlignment.Left;
				TextYAlignment = Enum.TextYAlignment.Bottom;
				Visible = Slider.Visible;
				ZIndex = 5;
				Parent = Container;
			})
			Groupbox:AddBlank(3, Slider.Visible);
		end

		local SliderOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, -4, 0, 13);
			Visible = Slider.Visible;
			ZIndex = 5;
			Parent = Container;
		})

		Library:RegisterSearchEntry(Groupbox, {
			Kind = 'Slider';
			Text = Slider.Text;
			Target = SliderOuter;
		})

		SliderOuter:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
			Slider.MaxSize = math.max(0, math.floor(SliderOuter.AbsoluteSize.X / Library:GetUIScale() + 0.5) - 2)
		end)

		Library:AddToRegistry(SliderOuter, { BorderColor3 = 'Black' })

		local SliderInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = SliderOuter;
		})

		Library:AddToRegistry(SliderInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local Fill = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderColor3 = Library.AccentColorDark;
			Size = UDim2.new(0, 0, 1, 0);
			ZIndex = 7;
			Parent = SliderInner;
		})

		Library:AddToRegistry(Fill, {
			BackgroundColor3 = 'AccentColor';
			BorderColor3 = 'AccentColorDark';
		})

		local HideBorderRight = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(1, 0, 0, 0);
			Size = UDim2.new(0, 1, 1, 0);
			ZIndex = 8;
			Parent = Fill;
		})

		Library:AddToRegistry(HideBorderRight, { BackgroundColor3 = 'AccentColor' })

		local DisplayLabel = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 14;
			Text = 'Infinite';
			ZIndex = 9;
			Parent = SliderInner;
		})

		local ValueBox = Library:Create('TextBox', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			ClearTextOnFocus = false;
			FontFace = Library.Font;
			Position = UDim2.new(0, 0, 0, 0);
			PlaceholderText = '';
			Size = UDim2.new(1, 0, 1, 0);
			Text = '';
			TextColor3 = Library.FontColor;
			TextSize = 14;
			TextStrokeTransparency = 0;
			TextXAlignment = Enum.TextXAlignment.Center;
			TextYAlignment = Enum.TextYAlignment.Center;
			Visible = false;
			ZIndex = 10;
			Parent = SliderInner;
		})

		Library:AddToRegistry(ValueBox, { TextColor3 = 'FontColor' })

		local IsTypingValue = false
		local UpdateDisplay
		local ApplyValue
		local TweenFillSize = createSizeTweener()

		local Round = createRounder(Slider.Rounding)

		local function FinishTyping(commit)
			if not IsTypingValue then return end
			IsTypingValue = false
			ValueBox.Visible = false
			DisplayLabel.Visible = true

			if commit then
				local typedValue = tonumber(ValueBox.Text)
				if typedValue then
					ApplyValue(typedValue)
				else
					UpdateDisplay()
				end
			else
				UpdateDisplay()
			end

			Library:AttemptSave()
		end

		local function BeginTyping()
			if Slider.Disabled or IsTypingValue then return end
			IsTypingValue = true
			ValueBox.Text = tostring(Slider.Value)
			ValueBox.Visible = true
			DisplayLabel.Visible = false
			pcall(function()
				ValueBox:CaptureFocus()
				ValueBox.CursorPosition = #ValueBox.Text + 1
			end)
		end

		ValueBox.FocusLost:Connect(function(enterPressed)
			FinishTyping(enterPressed)
		end)

		UpdateDisplay = function()
			local left = (Slider.Prefix or "")
			local right = (Slider.Suffix or "")

			local value = tostring(Round(Slider.Value))
			if not IsTypingValue then
				if Slider.Compact then
					DisplayLabel.Text = string.format('%s%s%s', Slider.Text .. ': ', value, right)
				elseif Slider.HideMax then
					DisplayLabel.Text = string.format('%s%s', value, right)
				else
					DisplayLabel.Text = string.format('%s%s/%s%s', left, value, tostring(Slider.Max), right)
				end
			else
				ValueBox.Text = tostring(Slider.Value)
			end

			local X = math.ceil(Library:MapValue(Slider.Value, Slider.Min, Slider.Max, 0, Slider.MaxSize))
			
			TweenFillSize(Fill, UDim2.new(0, X, 1, 0))
			HideBorderRight.Visible = not (X == Slider.MaxSize or X == 0)

			SliderInner.Visible = Slider.Visible
			SliderOuter.Visible = Slider.Visible
			DisplayLabel.Visible = Slider.Visible and not IsTypingValue
			ValueBox.Visible = Slider.Visible and IsTypingValue
		end

		ApplyValue = function(numOrStr)
			local Num = tonumber(numOrStr)
			if not Num then return end
			Num = math.clamp(Num, Slider.Min, Slider.Max)
			local old = Slider.Value
			Slider.Value = Num
			UpdateDisplay()
			if not Slider.Disabled and Num ~= old then
				Library:SafeCallback(Slider.Callback, Slider.Value)
				Library:SafeCallback(Slider.Changed, Slider.Value)
			end
		end

		Library:OnHighlight(SliderOuter, SliderOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		if type(Slider.Tooltip) == 'string' then
			Library:AddToolTip(Slider.Tooltip, SliderOuter)
		end

		function Slider:UpdateColors()
			Fill.BackgroundColor3 = Library.AccentColor
			Fill.BorderColor3     = Library.AccentColorDark
		end

		function Slider:GetValueFromXScale(scale)
			return Round(Library:MapValue(scale, 0, 1, Slider.Min, Slider.Max))
		end

		function Slider:GetValueFromXOffset(px)
			return Round(Library:MapValue(px, 0, Slider.MaxSize, Slider.Min, Slider.Max))
		end

		function Slider:Display()
			UpdateDisplay()
		end

		function Slider:SetValue(numOrStr)
			ApplyValue(numOrStr)
		end

		function Slider:SetText(t) if type(t) == "string" then Slider.Text = t; Slider:Display() end end
		function Slider:SetPrefix(p) if type(p) == "string" then Slider.Prefix = p; Slider:Display() end end
		function Slider:SetSuffix(s) if type(s) == "string" then Slider.Suffix = s; Slider:Display() end end
		function Slider:SetVisible(v) Slider.Visible = not not v; Slider:Display(); Groupbox:Resize() end
		function Slider:SetDisabled(d) Slider.Disabled = not not d; Slider:UpdateColors() end

		function Slider:OnChanged(Func)
			Slider.Changed = Func
			pcall(Func, Slider.Value)
		end

		SliderInner.InputBegan:Connect(function(Input)
			if Slider.Disabled then return end
			if Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame() then
				BeginTyping()
			elseif Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() and not IsTypingValue then
				local FillStartX = Fill.AbsolutePosition.X

				while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
					local nX = math.clamp((Mouse.X - FillStartX) / Library:GetUIScale(), 0, Slider.MaxSize)
					local nValue = Slider:GetValueFromXOffset(nX)
					local old = Slider.Value
					Slider.Value = nValue

					Slider:Display()

					if nValue ~= old then
						Library:SafeCallback(Slider.Callback, Slider.Value)
						Library:SafeCallback(Slider.Changed, Slider.Value)
					end

					RenderStepped:Wait()
				end

				Library:AttemptSave()
			end
		end)

		Slider:Display()
		Groupbox:AddBlank(Info.BlankSize or 6)
		Groupbox:Resize()

		aztup_options[Idx] = Slider
		Library:UpdateDependencyBoxes()
		return Slider
	end

	function Component.AddMinMaxSlider(self, Idx, Info)
		assert(Info.Text, 'AddMinMaxSlider: Missing slider text.')
		assert(Info.Min ~= nil, 'AddMinMaxSlider: Missing minimum value.')
		assert(Info.Max ~= nil, 'AddMinMaxSlider: Missing maximum value.')
		assert(Info.Rounding ~= nil, 'AddMinMaxSlider: Missing rounding value.')

		local defaultMin, defaultMax
		if type(Info.Default) == 'table' then
			defaultMin = Info.Default.Min or Info.Default[1]
			defaultMax = Info.Default.Max or Info.Default[2]
		end
		if defaultMin == nil then
			defaultMin = Info.DefaultMin
		end
		if defaultMax == nil then
			defaultMax = Info.DefaultMax
		end

		local minVal = tonumber(defaultMin) or Info.Min
		local maxVal = tonumber(defaultMax) or Info.Max

		minVal = math.clamp(minVal, Info.Min, Info.Max)
		maxVal = math.clamp(maxVal, Info.Min, Info.Max)
		if minVal > maxVal then
			minVal, maxVal = maxVal, minVal
		end

		local rangeValue = {
			Min = minVal;
			Max = maxVal;
		}

		local MinMaxSlider = {
			Value = rangeValue;
			Min = Info.Min;
			Max = Info.Max;
			Rounding = Info.Rounding;
			MaxSize = 232;
			Type = 'MinMaxSlider';

			Text = Info.Text;
			Prefix = type(Info.Prefix) == "string" and Info.Prefix or "";
			Suffix = type(Info.Suffix) == "string" and Info.Suffix or "";

			Visible = (type(Info.Visible) == "boolean") and Info.Visible or true;
			Disabled = (type(Info.Disabled) == "boolean") and Info.Disabled or false;

			Callback = Info.Callback or function(_) end;
			Changed = Info.Changed or function(_) end;
			Compact = not not Info.Compact;
			Tooltip = Info.Tooltip;
		}

		local Groupbox = self
		local Container = Groupbox.Container

		if not MinMaxSlider.Compact then
			Library:CreateLabel({
				Size = UDim2.new(1, 0, 0, 10);
				TextSize = 14;
				Text = MinMaxSlider.Text;
				TextXAlignment = Enum.TextXAlignment.Left;
				TextYAlignment = Enum.TextYAlignment.Bottom;
				Visible = MinMaxSlider.Visible;
				ZIndex = 5;
				Parent = Container;
			})
			Groupbox:AddBlank(3, MinMaxSlider.Visible);
		end

		local SliderOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, -4, 0, 13);
			Visible = MinMaxSlider.Visible;
			ZIndex = 5;
			Parent = Container;
		})

		Library:RegisterSearchEntry(Groupbox, {
			Kind = 'MinMaxSlider';
			Text = MinMaxSlider.Text;
			Target = SliderOuter;
		})

		SliderOuter:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
			MinMaxSlider.MaxSize = math.max(0, math.floor(SliderOuter.AbsoluteSize.X / Library:GetUIScale() + 0.5) - 2)
		end)

		Library:AddToRegistry(SliderOuter, { BorderColor3 = 'Black' })

		local SliderInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = SliderOuter;
		})

		Library:AddToRegistry(SliderInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local RangeFill = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderColor3 = Library.AccentColorDark;
			Size = UDim2.new(0, 0, 1, 0);
			ZIndex = 7;
			Parent = SliderInner;
		})

		Library:AddToRegistry(RangeFill, {
			BackgroundColor3 = 'AccentColor';
			BorderColor3 = 'AccentColorDark';
		})

		local HideBorderLeft = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 0, 0, 0);
			Size = UDim2.new(0, 1, 1, 0);
			ZIndex = 8;
			Parent = RangeFill;
		})

		local HideBorderRight = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(1, 0, 0, 0);
			Size = UDim2.new(0, 1, 1, 0);
			ZIndex = 8;
			Parent = RangeFill;
		})

		Library:AddToRegistry(HideBorderLeft, { BackgroundColor3 = 'AccentColor' })
		Library:AddToRegistry(HideBorderRight, { BackgroundColor3 = 'AccentColor' })

		local MinHandle = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColorDark;
			BorderSizePixel = 0;
			AnchorPoint = Vector2.new(0.5, 0);
			Size = UDim2.new(0, 2, 1, 0);
			ZIndex = 9;
			Parent = SliderInner;
		})

		local MaxHandle = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColorDark;
			BorderSizePixel = 0;
			AnchorPoint = Vector2.new(0.5, 0);
			Size = UDim2.new(0, 2, 1, 0);
			ZIndex = 9;
			Parent = SliderInner;
		})

		Library:AddToRegistry(MinHandle, { BackgroundColor3 = 'AccentColorDark' })
		Library:AddToRegistry(MaxHandle, { BackgroundColor3 = 'AccentColorDark' })

		local DisplayLabel = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 14;
			Text = 'Infinite';
			ZIndex = 9;
			Parent = SliderInner;
		})

		Library:OnHighlight(SliderOuter, SliderOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		if type(MinMaxSlider.Tooltip) == 'string' then
			Library:AddToolTip(MinMaxSlider.Tooltip, SliderOuter)
		end

		function MinMaxSlider:UpdateColors()
			RangeFill.BackgroundColor3 = Library.AccentColor
			RangeFill.BorderColor3 = Library.AccentColorDark
			MinHandle.BackgroundColor3 = Library.AccentColorDark
			MaxHandle.BackgroundColor3 = Library.AccentColorDark
		end

		local Round = createRounder(MinMaxSlider.Rounding)
		local TweenRangeFillSize = createSizeTweener()

		function MinMaxSlider:GetValueFromXOffset(px)
			return Round(Library:MapValue(px, 0, MinMaxSlider.MaxSize, MinMaxSlider.Min, MinMaxSlider.Max))
		end

		function MinMaxSlider:Display()
			local left = (MinMaxSlider.Prefix or "")
			local right = (MinMaxSlider.Suffix or "")
			local minText = string.format('%s%s%s', left, tostring(MinMaxSlider.Value.Min), right)
			local maxText = string.format('%s%s%s', left, tostring(MinMaxSlider.Value.Max), right)

			if MinMaxSlider.Compact then
				DisplayLabel.Text = string.format('%s%s - %s', MinMaxSlider.Text .. ': ', minText, maxText)
			else
				DisplayLabel.Text = string.format('%s - %s', minText, maxText)
			end

			local minX = math.ceil(Library:MapValue(MinMaxSlider.Value.Min, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))
			local maxX = math.ceil(Library:MapValue(MinMaxSlider.Value.Max, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))

			if maxX < minX then
				minX, maxX = maxX, minX
			end

			local width = math.max(0, maxX - minX)
			RangeFill.Position = UDim2.new(0, minX, 0, 0)
			RangeFill.Size =  UDim2.new(0, width, 1, 0)
			HideBorderLeft.Visible = not (minX == 0 or width == 0)
			HideBorderRight.Visible = not (maxX == MinMaxSlider.MaxSize or width == 0)

			MinHandle.Position = UDim2.new(0, minX, 0, 0)
			MaxHandle.Position = UDim2.new(0, maxX, 0, 0)

			SliderInner.Visible = MinMaxSlider.Visible
			SliderOuter.Visible = MinMaxSlider.Visible
		end

		function MinMaxSlider:SetValue(range)
			if type(range) ~= 'table' then return end
			local newMin = tonumber(range.Min or range[1])
			local newMax = tonumber(range.Max or range[2])
			if not newMin or not newMax then return end
			newMin = math.clamp(newMin, MinMaxSlider.Min, MinMaxSlider.Max)
			newMax = math.clamp(newMax, MinMaxSlider.Min, MinMaxSlider.Max)
			if newMin > newMax then
				newMin, newMax = newMax, newMin
			end
			local oldMin, oldMax = MinMaxSlider.Value.Min, MinMaxSlider.Value.Max
			MinMaxSlider.Value.Min = newMin
			MinMaxSlider.Value.Max = newMax
			MinMaxSlider:Display()
			if not MinMaxSlider.Disabled and (newMin ~= oldMin or newMax ~= oldMax) then
				Library:SafeCallback(MinMaxSlider.Callback, MinMaxSlider.Value)
				Library:SafeCallback(MinMaxSlider.Changed, MinMaxSlider.Value)
			end
		end

		function MinMaxSlider:SetText(t) if type(t) == "string" then MinMaxSlider.Text = t; MinMaxSlider:Display() end end
		function MinMaxSlider:SetPrefix(p) if type(p) == "string" then MinMaxSlider.Prefix = p; MinMaxSlider:Display() end end
		function MinMaxSlider:SetSuffix(s) if type(s) == "string" then MinMaxSlider.Suffix = s; MinMaxSlider:Display() end end
		function MinMaxSlider:SetVisible(v) MinMaxSlider.Visible = not not v; MinMaxSlider:Display(); Groupbox:Resize() end
		function MinMaxSlider:SetDisabled(d) MinMaxSlider.Disabled = not not d; MinMaxSlider:UpdateColors() end

		function MinMaxSlider:OnChanged(Func)
			MinMaxSlider.Changed = Func
			pcall(Func, MinMaxSlider.Value)
		end

		SliderInner.InputBegan:Connect(function(Input)
			if MinMaxSlider.Disabled then return end
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				local innerX = SliderInner.AbsolutePosition.X
				local minX = math.ceil(Library:MapValue(MinMaxSlider.Value.Min, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))
				local maxX = math.ceil(Library:MapValue(MinMaxSlider.Value.Max, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))
				local mouseX = math.clamp((Mouse.X - innerX) / Library:GetUIScale(), 0, MinMaxSlider.MaxSize)
				local dragTarget = (math.abs(mouseX - minX) <= math.abs(mouseX - maxX)) and 'Min' or 'Max'

				while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
					local nX = math.clamp((Mouse.X - innerX) / Library:GetUIScale(), 0, MinMaxSlider.MaxSize)
					local nValue = MinMaxSlider:GetValueFromXOffset(nX)
					local oldMin, oldMax = MinMaxSlider.Value.Min, MinMaxSlider.Value.Max

					if dragTarget == 'Min' then
						if nValue > MinMaxSlider.Value.Max then
							MinMaxSlider.Value.Min = MinMaxSlider.Value.Max
							MinMaxSlider.Value.Max = nValue
							dragTarget = 'Max'
						else
							MinMaxSlider.Value.Min = nValue
						end
					else
						if nValue < MinMaxSlider.Value.Min then
							MinMaxSlider.Value.Max = MinMaxSlider.Value.Min
							MinMaxSlider.Value.Min = nValue
							dragTarget = 'Min'
						else
							MinMaxSlider.Value.Max = nValue
						end
					end

					MinMaxSlider:Display()

					if MinMaxSlider.Value.Min ~= oldMin or MinMaxSlider.Value.Max ~= oldMax then
						Library:SafeCallback(MinMaxSlider.Callback, MinMaxSlider.Value)
						Library:SafeCallback(MinMaxSlider.Changed, MinMaxSlider.Value)
					end

					RenderStepped:Wait()
				end

				Library:AttemptSave()
			end
		end)

		MinMaxSlider:Display()
		Groupbox:AddBlank(Info.BlankSize or 6)
		Groupbox:Resize()

		aztup_options[Idx] = MinMaxSlider
		Library:UpdateDependencyBoxes()
		return MinMaxSlider
	end

	return Component
end  
end;

modules["@src/utility/librarys/components/toggle"] = function()



local signal = require("@src/utility/signal");
local curr_mode_select;
return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local RenderStepped = context.RenderStepped
	local BaseAddons = context.BaseAddons

	local Component = {}

	function Component.AddToggle(self, Idx, Info)
		assert(Info.Text, 'AddInput: Missing `Text` string.')
		if self.Objects then
			table.insert(self.Objects, {
				internal_name = Idx, settings = Info
			})
		else
			print(self)
		end;
		
		local Toggle = {
			Value = Info.Default or false;
			Type = 'Toggle';
			Flag = Idx,
			Name = Info.Text,
			
			Callback = Info.Callback or function(Value) end;
			Addons = {};
			Risky = Info.Risky;
		}

		local Groupbox = self;
		local Container = Groupbox.Container;

		local ToggleOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(0, 13, 0, 13);
			ZIndex = 5;
			Parent = Container;
		})

		Library:AddToRegistry(ToggleOuter, {
			BorderColor3 = 'Black';
		})

		local ToggleInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = ToggleOuter;
		})

		Library:AddToRegistry(ToggleInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local ToggleLabel = Library:CreateLabel({
			Size = UDim2.new(0, 236, 1, 0);
			Position = UDim2.new(1, 6, 0, 0);
			TextSize = 14;
			Text = Info.Text;
			TextXAlignment = Enum.TextXAlignment.Left;
			ZIndex = 6;
			Parent = ToggleInner;
		})

		Library:Create('UIListLayout', {
			Padding = UDim.new(0, 4);
			FillDirection = Enum.FillDirection.Horizontal;
			HorizontalAlignment = Enum.HorizontalAlignment.Right;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = ToggleLabel;
		})

		local ToggleRegion = Library:Create('Frame', {
			BackgroundTransparency = 1;
			Size = UDim2.new(0, 170, 1, 0);
			ZIndex = 8;
			Parent = ToggleOuter;
		})

		Library:OnHighlight(ToggleRegion, ToggleOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		function Toggle:UpdateColors()
			Toggle:Display();
		end;

		if type(Info.Tooltip) == 'string' then
			Library:AddToolTip(Info.Tooltip, ToggleRegion)
		end

		function Toggle:Display()
			ToggleInner.BackgroundColor3 = Toggle.Value and Library.AccentColor or Library.MainColor;
			ToggleInner.BorderColor3 = Toggle.Value and Library.AccentColorDark or Library.OutlineColor;

			Library.RegistryMap[ToggleInner].Properties.BackgroundColor3 = Toggle.Value and 'AccentColor' or 'MainColor';
			Library.RegistryMap[ToggleInner].Properties.BorderColor3 = Toggle.Value and 'AccentColorDark' or 'OutlineColor';
		end;
		Toggle.__internal = signal.new();

		function Toggle:OnChanged(Func)
			Toggle.Changed = Func;
			pcall(Func,Toggle.Value);
		end;

		function Toggle:SetValue(Bool)
			Bool = (not not Bool);

			Toggle.Value = Bool;
			Toggle:Display();

			for _, Addon in next, Toggle.Addons do
				if Addon.Type == 'KeyPicker' and Addon.SyncToggleState then
					Addon.Toggled = Bool
					Addon:Update()
				end
			end
			pcall(function()
				Library:SafeCallback(Toggle.Callback, Toggle.Value);
				Library:SafeCallback(Toggle.Changed, Toggle.Value);

				aztup_options.OnlyShowEnabledKeybinds.__internal:fire()
			end)
			Library:UpdateDependencyBoxes();
		end;

		ToggleRegion.InputBegan:Connect(function(Input)
			
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				Toggle:SetValue(not Toggle.Value)
				Library:AttemptSave();
			end;
		end);

		if Toggle.Risky then
			Library:RemoveFromRegistry(ToggleLabel)
			ToggleLabel.TextColor3 = Library.RiskColor
			Library:AddToRegistry(ToggleLabel, { TextColor3 = 'RiskColor' })
		end

		Toggle:Display();
		if type(Info.Text) == 'string' and Info.Text ~= '' then
			Library:RegisterSearchEntry(Groupbox, {
				Kind = 'Toggle';
				Text = Info.Text;
				Tab = Groupbox.Tab or Groupbox;
				Target = ToggleOuter;
				Focus = function()
					Library:FocusSearchTarget(ToggleOuter)
				end;
			})
		end
		Groupbox:AddBlank(Info.BlankSize or 5 + 2);
		Groupbox:Resize();

		Toggle.TextLabel = ToggleLabel;
		Toggle.Container = Container;
		setmetatable(Toggle, BaseAddons or {})

		aztup_toggles[Idx] = Toggle;

		Library:UpdateDependencyBoxes();

		return Toggle	
end

	function Component.AddKeyPicker(self, Idx, Info)
		local ParentObj = self;
		local ToggleLabel = self.TextLabel;
		local Container = self.Container;
		
		
		

		assert(Info.Default, 'AddKeyPicker: Missing default value.');

		local KeyPicker = {
			Value = Info.Default;
			Toggled = false;
			Mode = Info.Mode or 'Toggle'; 
			Type = 'KeyPicker';
			Callback = Info.Callback or function(Value) end;
			ChangedCallback = Info.ChangedCallback or function(New) end;

			SyncToggleState = Info.SyncToggleState or false;
		};

		local Modes = Info.Modes or { 'Toggle', 'Hold' };

		self.KeyPicker = {
			Flag = Idx;
			Value = KeyPicker.Value
		}

		if not table.find(Modes, KeyPicker.Mode) then
			KeyPicker.Mode = Modes[1]
		end

		local ContainerLabelTransparencyTween
		local ContainerStrokeTransparencyTween

		local PickOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(0, 28, 0, 15);
			ZIndex = 6;
			Parent = ToggleLabel;
		});

		local PickInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 7;
			Parent = PickOuter;
		});

		Library:AddToRegistry(PickInner, {
			BackgroundColor3 = 'BackgroundColor';
			BorderColor3 = 'OutlineColor';
		});

		local DisplayLabel = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 13;
			Text = Info.Default;
			TextWrapped = true;
			ZIndex = 8;
			Parent = PickInner;
			Name = "DisplayLabelKeybind";
		});

		local ModeSelectOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.fromOffset(ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4, ToggleLabel.AbsolutePosition.Y + 1);
			Size = UDim2.new(0, 60, 0, (((#Modes)+1) * 15) + 2);
			Visible = false;
			ZIndex = 14;
			Parent = Library.ScreenGui;
		});

		Library:AddUIScale(ModeSelectOuter);

		ToggleLabel:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			ModeSelectOuter.Position = UDim2.fromOffset(ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4, ToggleLabel.AbsolutePosition.Y + 1);
		end);

		local ModeSelectInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 15;
			Parent = ModeSelectOuter;
		});

		Library:AddToRegistry(ModeSelectInner, {
			BackgroundColor3 = 'BackgroundColor';
			BorderColor3 = 'OutlineColor';
		});

		Library:Create('UIListLayout', {
			FillDirection = Enum.FillDirection.Vertical;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = ModeSelectInner;
		});

		local ContainerLabel, ContainerStroke = Library:CreateLabel({
			TextXAlignment = Enum.TextXAlignment.Left;
			Size = UDim2.new(1, 0, 0, 18);
			TextSize = 16;
			Visible = false;
			ZIndex = 110;
			Parent = Library.KeybindContainer;
		}, true);
		
		task.spawn(function()
			ContainerLabel.FontFace = lexend.regular;
		end);

		local ModeButtons = {};

		local function GetKeybindFrameResizeBaseline()
			local ResizeTarget = Library.KeybindFrameResizeTarget

			if Library.KeybindFrameResizeTween and ResizeTarget then
				return ResizeTarget.Height, ResizeTarget.PositionY, ResizeTarget.CenterY
			end

			local CurrentHeight = Library.KeybindFrame.AbsoluteSize.Y / Library:GetUIScale()
			local CurrentPositionY = Library.KeybindFrame.Position.Y.Offset
			local CurrentCenterY = Library.KeybindFrame.AbsolutePosition.Y + (Library.KeybindFrame.AbsoluteSize.Y * 0.5)

			return CurrentHeight, CurrentPositionY, CurrentCenterY
		end

		for Idx, Mode in next, Modes do
			local ModeButton = {};

			local Label = Library:CreateLabel({
				Active = false;
				Size = UDim2.new(1, 0, 0, 15);
				TextSize = 13;
				Text = Mode;
				ZIndex = 16;
				Parent = ModeSelectInner;
			});

			function ModeButton:Select()
				for _, Button in next, ModeButtons do
					Button:Deselect();
				end;

				KeyPicker.Mode = Mode;

				Label.TextColor3 = Library.AccentColor;
				Library.RegistryMap[Label].Properties.TextColor3 = 'AccentColor';
				curr_mode_select = nil;
				ModeSelectOuter.Visible = false;
			end;

			function ModeButton:Deselect()
				KeyPicker.Mode = nil;

				Label.TextColor3 = Library.FontColor;
				Library.RegistryMap[Label].Properties.TextColor3 = 'FontColor';
			end;

			Label.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					ModeButton:Select();
					Library:AttemptSave();
				end;
			end);

			if Mode == KeyPicker.Mode then
				ModeButton:Select();
			end;

			ModeButtons[Mode] = ModeButton;
		end;

		(function()

			local ModeButton = {};

			local Label = Library:CreateLabel({
				Active = false;
				Size = UDim2.new(1, 0, 0, 15);
				TextSize = 13;
				Text = "Unbind";
				ZIndex = 16;
				Parent = ModeSelectInner;
			});

			function ModeButton:Deselect() end;

			function ModeButton:Select()
				local Key = "None";
				
				DisplayLabel.Text = Key == "None" and "N/A" or Key;
				KeyPicker.Value = Key;
				Library:SafeCallback(KeyPicker.ChangedCallback, Enum.KeyCode.Unknown)
				if KeyPicker.Changed then
					Library:SafeCallback(KeyPicker.Changed, Enum.KeyCode.Unknown)
				end;
				curr_mode_select = nil;
				ModeSelectOuter.Visible = false;
				Library:AttemptSave();
			end;

			Label.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					ModeButton:Select();
					Library:AttemptSave();
				end;
			end);

			ModeButtons.Unbind = ModeButton;
		end)();

		local function UpdateKeybindFrameSize()
			Library.KeybindFrameResizeQueued = false

			if Info.NoUI then return end

			local YSize = 0
			local XSize = 0
			for _, Label in next, Library.KeybindContainer:GetChildren() do
				if Label:IsA('TextLabel') then
					if Label.Visible and not Label:GetAttribute('KeybindFadingOut') then
						YSize = YSize + 18
					end

					local LabelWidth = Label.TextBounds.X / Library:GetUIScale()
					if Label.Visible and (LabelWidth > XSize) then
						XSize = LabelWidth
					end
				end
			end

			local OldHeight, BaselinePositionY, BaselineCenterY = GetKeybindFrameResizeBaseline()
			local NewHeight = YSize == 0 and 24 or YSize + 32
			local NewWidth = math.max(XSize + 34, 220)
			local TargetPositionY = BaselinePositionY
			local TargetCenterY = BaselineCenterY

			local properties = {
				Size = UDim2.new(0, NewWidth, 0, NewHeight);
				Position = UDim2.fromOffset(Library.KeybindFrame.Position.X.Offset, TargetPositionY);
			}
			if NewHeight ~= OldHeight then 
				local Camera = workspace.CurrentCamera
				local ViewportY = (Camera and Camera.ViewportSize.Y) or 1080
				local CenterY = ViewportY * 0.5
				local NormalizedDistance = math.abs(BaselineCenterY - CenterY) / ViewportY

				if NormalizedDistance > 0.10 then
					
					local HeightDelta = (NewHeight - OldHeight) * Library:GetUIScale()
					local Direction = (BaselineCenterY < CenterY) and 1 or -1
					TargetPositionY = BaselinePositionY + (HeightDelta * 0.5 * Direction)
					TargetCenterY = BaselineCenterY + (HeightDelta * 0.5 * Direction)
					properties.Position = UDim2.fromOffset(Library.KeybindFrame.Position.X.Offset, TargetPositionY)
				end
			end

			if Library.KeybindFrameResizeTween then
				Library.KeybindFrameResizeTween:Cancel()
				Library.KeybindFrameResizeTween = nil
			end

			local tweenInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			local Tween = services.TweenService:Create(Library.KeybindFrame, tweenInfo, properties)
			Library.KeybindFrameResizeTween = Tween
			Library.KeybindFrameResizeTarget = {
				Height = NewHeight;
				PositionY = TargetPositionY;
				CenterY = TargetCenterY;
			}

			Tween.Completed:Connect(function()
				if Library.KeybindFrameResizeTween == Tween then
					Library.KeybindFrameResizeTween = nil
				end
			end)

			Tween:Play()
		end

		local function QueueKeybindFrameSize()
			if Library.KeybindFrameResizeQueued then
				return
			end

			Library.KeybindFrameResizeQueued = true
			task.defer(UpdateKeybindFrameSize)
		end

		function KeyPicker:Update()
		    if Info.NoUI then return end

		    local State = KeyPicker:GetState()
		    local shouldHide = (not State and aztup_toggles.OnlyShowEnabledKeybinds and aztup_toggles.OnlyShowEnabledKeybinds.Value)
		                   or (KeyPicker.Value == "None")

			if Info.KeybindOnly then
				State = false;
				shouldHide = (KeyPicker.Value == "None")
			end;

			if #tostring(KeyPicker.Value) == 0 then
			   	shouldHide = true
			end;

		    
		    ContainerLabel.Text = string.format('[%s]: %s', KeyPicker.Value, Info.Text)
		    local x, _ = Library:GetLexendTextBounds(ContainerLabel.Text, lexend.regular, 16)
		    ContainerLabel.LayoutOrder = -x
		    ContainerLabel.TextColor3 = State and Library.AccentColor or Library.FontColor
		    Library.RegistryMap[ContainerLabel].Properties.TextColor3 = State and 'AccentColor' or 'FontColor'

		    if shouldHide then
		        
		        if ContainerLabel.Visible and not ContainerLabel:GetAttribute('KeybindFadingOut') then
		            if ContainerLabelTransparencyTween then
		                ContainerLabelTransparencyTween:Cancel()
		                ContainerLabelTransparencyTween = nil
		            end

		            if ContainerStrokeTransparencyTween then
		                ContainerStrokeTransparencyTween:Cancel()
		                ContainerStrokeTransparencyTween = nil
		            end

		            ContainerLabel:SetAttribute('KeybindFadingOut', true)

		            local fadeOut = services.TweenService:Create(ContainerLabel, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                TextTransparency = 1
		            })
		            ContainerLabelTransparencyTween = fadeOut
		            fadeOut:Play()

				local strokeFadeOut = services.TweenService:Create(ContainerStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                Transparency = 1
				})
				ContainerStrokeTransparencyTween = strokeFadeOut
				strokeFadeOut:Play()
				fadeOut.Completed:Connect(function(playbackState)
					if ContainerLabelTransparencyTween ~= fadeOut then
						return
					end

					ContainerLabelTransparencyTween = nil
					ContainerStrokeTransparencyTween = nil

						if playbackState ~= Enum.PlaybackState.Completed or not ContainerLabel.Visible or KeyPicker:GetState() then
						ContainerLabel:SetAttribute('KeybindFadingOut', nil)
							return
						end

						ContainerLabel.Visible = false
					ContainerLabel:SetAttribute('KeybindFadingOut', nil)
						KeyPicker:Update()
		            end)
		        end
		        
		    else
				if ContainerLabel:GetAttribute('KeybindFadingOut') then
					ContainerLabel:SetAttribute('KeybindFadingOut', nil)
				end

				if ContainerLabelTransparencyTween then
					ContainerLabelTransparencyTween:Cancel()
					ContainerLabelTransparencyTween = nil
				end

				if ContainerStrokeTransparencyTween then
					ContainerStrokeTransparencyTween:Cancel()
					ContainerStrokeTransparencyTween = nil
				end

		        
		        if not ContainerLabel.Visible then
		            ContainerLabel.Visible = true
		            ContainerLabel.TextTransparency = 1
		            ContainerStroke.Transparency = 1
		            local fadeIn = services.TweenService:Create(ContainerLabel, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                TextTransparency = 0
		            })
		            ContainerLabelTransparencyTween = fadeIn
		            fadeIn:Play()
					
				local strokeFadeIn = services.TweenService:Create(ContainerStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                Transparency = 0
				})
				ContainerStrokeTransparencyTween = strokeFadeIn
				strokeFadeIn:Play()
		        else
		            
					ContainerStroke.Transparency = 0
		            ContainerLabel.TextTransparency = 0
		        end
		    end

			Library.RegistryMap[ContainerLabel].KEYBINDLABEL = true;
			Library.RegistryMap[ContainerLabel].Properties.TextColor3 = State and 'AccentColor' or 'FontColor';

			QueueKeybindFrameSize()
		end;

		function KeyPicker:GetState()
			if KeyPicker.Mode == 'Always' then
				return true			
elseif KeyPicker.Mode == 'Hold' then
				if KeyPicker.Value == 'None' then
					return false				
end

				local Key = KeyPicker.Value;

				if Key == 'MB1' or Key == 'MB2' then
					return Key == 'MB1' and InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
						or Key == 'MB2' and InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)				
else
					return InputService:IsKeyDown(Enum.KeyCode[KeyPicker.Value])				
end;
			else
				return KeyPicker.Toggled			
end;
		end;

		function KeyPicker:SetValue(Data)
			local Key, Mode = Data[1], Data[2];
			DisplayLabel.Text = Key == "None" and "N/A" or Key;
			KeyPicker.Value = Key;
			ModeButtons[Mode]:Select();
			KeyPicker:Update();
		end;

		function KeyPicker:OnClick(Callback)
			KeyPicker.Clicked = Callback
		end

		function KeyPicker:OnChanged(Callback)
			KeyPicker.Changed = Callback
			Callback(KeyPicker.Value)
		end

		if ParentObj.Addons then
			table.insert(ParentObj.Addons, KeyPicker)
		end

		function KeyPicker:DoClick()
			if ParentObj.Type == 'Toggle' and KeyPicker.SyncToggleState then
				if KeyPicker.Mode == 'Hold' then
					ParentObj:SetValue(KeyPicker.Toggled)
				else
					ParentObj:SetValue(not ParentObj.Value)
				end
			end

			Library:SafeCallback(KeyPicker.Callback, KeyPicker.Toggled)
			Library:SafeCallback(KeyPicker.Clicked, KeyPicker.Toggled)
			self:Update()
		end

		local Picking = false;

		PickOuter.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				xpcall(function()
					Picking = true;
					DisplayLabel.Text = '';
					local Break;
					local Text = '';
					task.spawn(function()
						pcall(function()
							while (not Break) do
								if Text == '...' then
									Text = '';
								end;
								Text = Text .. '.';
								DisplayLabel.Text = Text;
								wait(0.4);
							end;
						end)
					end);
					wait(0.2);
					local Event;
					Event = InputService.InputBegan:Connect(function(Input)
						local Key;
						local kc = Input.KeyCode;
						if Input.UserInputType == Enum.UserInputType.Keyboard then
							Key = Input.KeyCode.Name;
							if kc == Enum.KeyCode.Backspace or kc == Enum.KeyCode.Escape then
								Key = 'None'
								kc = Enum.KeyCode.Unknown;
							end;
						elseif Input.UserInputType == Enum.UserInputType.MouseButton1 then
							Key = 'MB1';
						elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
							Key = 'MB2';
						end;
						Break = true;
						Picking = false;

						Event:Disconnect();
						DisplayLabel.Text = Key == "None" and "N/A" or Key;
						KeyPicker.Value = Key;
						Library:SafeCallback(KeyPicker.ChangedCallback, kc or Input.UserInputType)
						Library:SafeCallback(KeyPicker.Changed, kc or Input.UserInputType)
						Library:AttemptSave();
					end);
				end, print);
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame() then
				if curr_mode_select then
					curr_mode_select.Visible = false;
					curr_mode_select = nil;
				end

				curr_mode_select = ModeSelectOuter;
				ModeSelectOuter.Visible = true;
			end;
		end);

		local function IsBoundInput(Input, Processed)
			local Key = KeyPicker.Value;

			if Key == 'None' then
				return false
			end

			if Key == 'MB1' then
				return Input.UserInputType == Enum.UserInputType.MouseButton1
		elseif Key == 'MB2' then
				return Input.UserInputType == Enum.UserInputType.MouseButton2
		end

			return Input.UserInputType == Enum.UserInputType.Keyboard and not Processed and Input.KeyCode.Name == Key
		end

		local function IsBoundInputEnded(Input)
			local Key = KeyPicker.Value;

			if Key == 'None' then
				return false
			end

			if Key == 'MB1' then
				return Input.UserInputType == Enum.UserInputType.MouseButton1
			elseif Key == 'MB2' then
				return Input.UserInputType == Enum.UserInputType.MouseButton2
			end

			return Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Key
		end

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input,t)
			if (not Picking) then
				if KeyPicker.Mode == 'Toggle' then
					if IsBoundInput(Input, t) then
						KeyPicker.Toggled = not KeyPicker.Toggled
						KeyPicker:DoClick();
						KeyPicker:Update();
					end;
				elseif KeyPicker.Mode == 'Hold' then
					if IsBoundInput(Input, t) then
						if not KeyPicker.Toggled then
							KeyPicker.Toggled = true
							KeyPicker:DoClick();
						end
						KeyPicker:Update();
					end
				end;
			end;

			if not Library.Toggled then
				return			
end;
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				local AbsPos, AbsSize = ModeSelectOuter.AbsolutePosition, ModeSelectOuter.AbsoluteSize;

				if Mouse.X < AbsPos.X or Mouse.X > AbsPos.X + AbsSize.X
					or Mouse.Y < (AbsPos.Y - 20 - 1) or Mouse.Y > AbsPos.Y + AbsSize.Y then
					curr_mode_select = nil;
					ModeSelectOuter.Visible = false;
				end;
			end;
		end))

		Library:GiveSignal(InputService.InputEnded:Connect(function(Input)
			if (not Picking) then
				if KeyPicker.Mode == 'Hold' and KeyPicker.Toggled and IsBoundInputEnded(Input) then
					KeyPicker.Toggled = false
					KeyPicker:DoClick();
				end
			end;
		end))

		loaded_signal:connect(function()
			KeyPicker:Update()
		end)
		KeyPicker:Update();

		aztup_options[Idx] = KeyPicker;

		return self	
end

	return Component
end
end;

modules["@src/utility/librarys/luraph_sdk"] = function()
return loadstring([[
    local assert = assert
local type = type
local setfenv = setfenv

getfenv().LPH_JIT = function(f, ...)
    assert(type(f) == "function" and #{...} == 0, "LPH_JIT only accepts a single constant function as an argument.")
    return f
end
LPH_JIT_MAX = LPH_JIT

getfenv().LPH_NO_VIRTUALIZE = function(f, ...)
    assert(type(f) == "function" and #{...} == 0, "LPH_NO_VIRTUALIZE only accepts a single constant function as an argument.")
    return f
end

getfenv().LPH_NO_UPVALUES = function(f, ...)
    assert(type(setfenv) == "function", "LPH_NO_UPVALUES can only be used on Lua versions with getfenv & setfenv")
    assert(type(f) == "function" and #{...} == 0, "LPH_NO_UPVALUES only accepts a single constant function as an argument.")
    return f
end

getfenv().LPH_CRASH = function(...)
    assert(#{...} == 0, "LPH_CRASH does not accept any arguments.")
end
]])()
end;

modules["@src/utility/librarys/managers/SaveManager"] = function()

aztup_options = getgenv().aztup_options;
local cloneref = cloneref or function(a) return a end;
local httpService = cloneref(game:GetService('HttpService'));

local auto_loading = false;
local SaveManager = {} do
	SaveManager.Folder = 'LinoriaLibSettings'
	SaveManager.Ignore = {}
	SaveManager.Parser = {
		Toggle = {
			Save = function(idx, object) 
				return { type = 'Toggle', idx = idx, value = object.Value } 
			end,
			Load = function(idx, data)
				if aztup_toggles[idx] and aztup_toggles[idx].Value ~= data.value then 
					task.spawn(function()
						aztup_toggles[idx]:SetValue(data.value)
					end);
				end
			end,
		},
		MinMaxSlider = {
			Save = function(idx, object)
				return { 
					type = 'MinMaxSlider', 
					idx = idx,
					Min = string.format("%.2f", object.Value.Min),
					Max = string.format("%.2f", object.Value.Max),
				}
			end,
			Load = function(idx, data)
				if aztup_options[idx] then  
					task.spawn(function()
						aztup_options[idx]:SetValue({
							Min = data.Min,
							Max = data.Max
						})
					end)
				end
			end,
		},
		Slider = {
			Save = function(idx, object) 
				return { type = 'Slider', idx = idx, value = tostring(object.Value) }
			end,
			Load = function(idx, data)
				if aztup_options[idx] then  
					task.spawn(function()
						aztup_options[idx]:SetValue(data.value)
					end)
				end
			end,
		},
		Dropdown = {
			Save = function(idx, object)
				return { type = 'Dropdown', idx = idx, value = object.Value, multi = object.Multi }
			end,
			Load = function(idx, data)
				if aztup_options[idx] then 
					if auto_loading then
						aztup_options[idx]:SetValue(data.value, true)
					else
						aztup_options[idx]:SetValue(data.value)
					end
				end
			end,
		},
		ColorPicker = {
			Save = function(idx, object)
				return { type = 'ColorPicker', idx = idx, value = object.Value:ToHex(), transparency = object.Transparency }
			end,
			Load = function(idx, data)
				if aztup_options[idx] then 
					aztup_options[idx]:SetValueRGB(Color3.fromHex(data.value), data.transparency)
				end
			end,
		},
		KeyPicker = {
			Save = function(idx, object)
				return { type = 'KeyPicker', idx = idx, mode = object.Mode, key = object.Value }
			end,
			Load = function(idx, data)
				if aztup_options[idx] then 
					aztup_options[idx]:SetValue({ data.key, data.mode })
				end
			end,
		},

		Input = {
			Save = function(idx, object)
				return { type = 'Input', idx = idx, text = object.Value }
			end,
			Load = function(idx, data)
				if aztup_options[idx] and type(data.text) == 'string' then
					aztup_options[idx]:SetValue(data.text)
				end
			end,
		},
	}

	function SaveManager:SetIgnoreIndexes(list)
		for _, key in next, list do
			self.Ignore[key] = true
		end
	end

	function SaveManager:SetFolder(folder)
		self.Folder = folder;
		self:BuildFolderTree()
	end

	function SaveManager:Save(name)
		if not name then
			return false, "no config file is selected"
		end

		local fullPath = self.Folder .. "/Settings/" .. name .. ".json"

		local function udimToTable(udim)
			return {
				["S"] = udim.Scale,
				["O"] = udim.Offset,
			}
		end


		local function udim2ToTable(udim2)
			return {
				["X"] = udimToTable(udim2.X),
				["Y"] = udimToTable(udim2.Y),
				["W"] = udimToTable(udim2.Width),
				["H"] = udimToTable(udim2.Height),
			}
		end

		local function udim2NoOffset(udim2: UDim2)
			return {
				["X"] = udimToTable(udim2.X),
				["Y"] = udimToTable(udim2.Y),
				["W"] = udimToTable(udim2.Width),
				["H"] = udimToTable(udim2.Height),
			}
		end

		local data = {
			objects = {},
			infoLoggerPosition = udim2ToTable(Library.InfoLoggerFrame.Position),
			keybindPosition = udim2ToTable(Library.KeybindFrame.Position),
			watermarkPosition = udim2ToTable(Library.Watermark.Position),
		}

		if aztup and aztup.proximity then
			data.proximityPosition = udim2NoOffset(aztup.proximity.Position);
			data.proximityTrans = aztup.proximity.BackgroundTransparency;
		end;

		pcall(function() 
			if aztup and aztup.spotify_widget then
				data.spotifyWidgetPosition = udim2ToTable(aztup.spotify_widget.Position);
			end;
		end);

		for idx, toggle in next, aztup_toggles do
			if self.Ignore[idx] then
				continue
			end

			table.insert(data.objects, self.Parser[toggle.Type].Save(idx, toggle))
		end

		for idx, option in next, aztup_options do
			if not self.Parser[option.Type] then
				continue
			end
			if self.Ignore[idx] then
				continue
			end

			table.insert(data.objects, self.Parser[option.Type].Save(idx, option))
		end

		local success, encoded = pcall(httpService.JSONEncode, httpService, data)
		if not success then
			return false, "failed to encode data"
		end

		writefile(fullPath, encoded)
		return true
	end

	function SaveManager:Load(name)
		if not name then
			return false, "no config file is selected"
		end

		local file = self.Folder .. "/Settings/" .. name .. ".json"
		if not isfile(file) then
			return false, "invalid file"
		end 

		local success, decoded = pcall(httpService.JSONDecode, httpService, readfile(file))
		if not success then
			return false, "decode error"
		end

		for _, option in next, decoded.objects do
			if self.Parser[option.type] then
				Logger.log_for_devs(("[save-manager] loading %s with option type of %s and value of %s"):format(option.type, option.idx, tostring(option.value)));
				self.Parser[option.type].Load(option.idx, option)
			end
		end

		local function tableToUdim(table)
			return UDim.new(table["S"], table["O"])
		end

		local function tableToUdim2(table)
			return UDim2.new(
				tableToUdim(table["X"]),
				tableToUdim(table["Y"]),
				tableToUdim(table["W"]),
				tableToUdim(table["H"])
			)
		end

		local function tableToUdim2_no_offset(table)
			return UDim2.new(
				tableToUdim(table["X"]),
				0,
				
				tableToUdim(table["W"]),
				0
				
			)
		end

		local function tableToUdim2_no_scale(table)
			return UDim2.new(
				tableToUdim(table["X"]),
				tableToUdim(table["Y"]),
				tableToUdim(table["W"]),
				tableToUdim(table["H"])
			)
		end

		if decoded.watermarkPosition then
			Library.Watermark.Position = tableToUdim2(decoded.watermarkPosition)
		end

		if aztup and aztup.proximity and decoded.proximityPosition then
			aztup.proximity.Position = tableToUdim2(decoded.proximityPosition);
			pcall(function()
				aztup.features.proximity_list:set_transparency(decoded.proximityTrans);
			end)

		end;

		pcall(function() 
			if aztup and aztup.spotify_widget and decoded.spotifyWidgetPosition then
				aztup.spotify_widget.Position = tableToUdim2(decoded.spotifyWidgetPosition);
			end;
		end);

		if decoded.keybindPosition and decoded.infoLoggerPosition then
			Library.KeybindFrame.Position = tableToUdim2(decoded.keybindPosition)
			Library.InfoLoggerFrame.Position = tableToUdim2(decoded.infoLoggerPosition)
			if decoded.chatLoggerSize and game:GetService("CoreGui"):FindFirstChild("thisisachatloggerpleasebanme") then
				local chat_logger = game:GetService("CoreGui"):FindFirstChild("thisisachatloggerpleasebanme");
				chat_logger.Frame.Size = tableToUdim2(decoded.chatLoggerSize);
				chat_logger.Frame.Position = tableToUdim2(decoded.chatLoggerPosition);
			end;
		end

		pcall(function() 
			if not persistent_data:get("automation_webhook") then return end

        	local webhook_url = aztup_options.automation_webhook.Value
        	if not webhook_url:find("discord.com/api/webhooks", 1, true) then
        	    
        	    return
        	end
		
        	persistent_data:set("automation_webhook", webhook_url)
		end);

		return true
	end
	function SaveManager:IgnoreThemeSettings()
		self:SetIgnoreIndexes({ 
			"BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor", 
			"ThemeManager_ThemeList", 'ThemeManager_CustomThemeList', 'ThemeManager_CustomThemeName', 
		})
	end

	function SaveManager:BuildFolderTree()
		local paths = {
			self.Folder,
			self.Folder .. '/themes',
			self.Folder .. '/settings'
		}

		for i = 1, #paths do
			local str = paths[i]
			if not isfolder(str) then
				makefolder(str)
			end
		end
	end

	function SaveManager:RefreshConfigList()
		local list = listfiles(self.Folder .. '/settings')

		local out = {}
		for i = 1, #list do
			local file = list[i]
			if file:sub(-5) == '.json' then
				

				local pos = file:find('.json', 1, true)
				local start = pos

				local char = file:sub(pos, pos)
				while char ~= '/' and char ~= '\\' and char ~= '' do
					pos = pos - 1
					char = file:sub(pos, pos)
				end

				if char == '/' or char == '\\' then
					table.insert(out, file:sub(pos + 1, start - 1))
				end
			end
		end
		
		return out
	end

	function SaveManager:SetLibrary(library)
		self.Library = library
	end

	function SaveManager:LoadAutoloadConfig()
		if isfile(("%s/settings/autoload-%i.txt"):format(self.Folder, game.PlaceId)) then
			local name = readfile(("%s/settings/autoload-%i.txt"):format(self.Folder, game.PlaceId))

			auto_loading = true;
			local success, err = self:Load(name)
			auto_loading = false;
			if isfile("Project Rain/silent_mode_toggle") then return end

			if not success then
				return self.Library:NotifyWithSound('Failed to load autoload config: ' .. err, 50)
			end

			return self.Library:Notify(string.format('Auto loaded config %q', name))
		end

		if isfile(self.Folder .. '/settings/autoload.txt') then
			local name = readfile(self.Folder .. '/settings/autoload.txt')

			auto_loading = true;
			local success, err = self:Load(name)
			auto_loading = false;
			if isfile("Project Rain/silent_mode_toggle") then return end

			if not success then
				return self.Library:NotifyWithSound('Failed to load autoload config: ' .. err, 50)
			end

			return self.Library:Notify(string.format('Auto loaded config %q', name))
		end
	end

	function SaveManager:BuildOtherSection(tab)
		local section = tab:AddRightGroupbox('Other')

		section:AddLabel("Build ID __BUILD__")

		section:AddButton({
			Text = "Switch to Nightly Branch (reexec needed)",
			Func = function()
				writefile("Project Rain/nightliy-branch", "true");
			end,
			DoubleClick = true
		})
		
		section:AddToggle('OnlyShowEnabledKeybinds', {
			Text = 'Only Show Enabled Keybinds',
			false,
			'Only Show Enabled Keybinds'
		})

		section:AddToggle('WatermarkShowsMem', {
			Text = 'Show Memory On Watermark',
			true,
			'Displays the memory data on the watermark.'
		})

		section:AddToggle('notification_sound', {
			Text = 'UI Sounds',
			true,
			'UI Sounds'
		})

		section:AddToggle('KeybindShower', {
			Text = 'Show Keybinds',
			false,
			'Shows Keybinds'
		})

		section:AddToggle('auto_hide_hud', {
			Text = 'Auto Hide HUD',
			false,
			'Auto hides the HUD when the backpack is open.'
		})

		section:AddToggle('BlurWhileOpen', {
			Text = "Blur Game",
			false,
			"Blurs the game whilst the ui is open."
		})

		section:AddToggle('Watermark', {
			Text = 'Watermark',
			true,
			'Displays the script being used.'
		})

		section:AddToggle('Console', {
			Text = 'Console',
			false,
			'Console'
		})
		
		section:AddSlider('NotificationVolume', {
			Text = "Notification Volume",
			Default = 1.3,
			Min = 0.1,
			Suffix = "vol", 
			Max = 10,
			Rounding = 1,
			Compact = false
		})

		local pendingScale;
		section:AddSlider('UIScale', {
			Text = "UI Scale",
			Default = 100,
			Min = 50,
			Max = 200,
			Suffix = "%",
			Rounding = 0,
			Compact = false,
			Tooltip = "Scales the menu and widgets. Applied when you release the slider.",
			Callback = function(value)
				
				local waiting = pendingScale ~= nil;
				pendingScale = value;
				if waiting then return end

				task.spawn(function()
					local InputService = game:GetService('UserInputService');
					while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
						task.wait();
					end

					local target = pendingScale;
					pendingScale = nil;
					self.Library:SetUIScale(target / 100);
					pcall(writefile, self.Folder .. '/settings/ui_scale.txt', tostring(target));
				end)
			end
		})

		
		self:SetIgnoreIndexes({ 'UIScale' });
		local savedScale = isfile(self.Folder .. '/settings/ui_scale.txt') and tonumber(readfile(self.Folder .. '/settings/ui_scale.txt'));
		if savedScale then
			aztup_options.UIScale:SetValue(savedScale);
			self.Library:SetUIScale(savedScale / 100);
		end

		aztup_toggles.OnlyShowEnabledKeybinds:OnChanged(function()
			for _, option in aztup_options do
				if option.Type == 'KeyPicker' and option.Update then
					option:Update();
				end
			end
		end)
		
		aztup_toggles.Watermark:OnChanged(function()
			Library:SetWatermarkVisibility(aztup_toggles.Watermark.Value)
		end)

		aztup_toggles.Console:OnChanged(function()
			Library:SetInfoLoggerVisibility(aztup_toggles.Console.Value)
			Library:UpdateInfoLoggerSize()
		end)
		
		aztup_toggles.KeybindShower:OnChanged(function()
			self.Library.KeybindFrame.Visible = aztup_toggles.KeybindShower.Value;
		end)

		section:AddButton({
			Text = 'Unload Script Instance',
			Func = function()
				if env.aztup then
					if env.Markers then   
						for _, marker in env.Markers:get() do
							marker:Destroy(); 
						end;
						table.clear(env.Markers._marked_instances);
						table.clear(env.Markers);
						getgenv().Markers = nil;
					end;
				
					pcall(function()
						env.aztup:detach();
					end);
					env.aztup = nil;
				end;
			end,
			DoubleClick = true
		})

		   
		local silent_val = isfile("Project Rain/silent_mode_toggle"); 
		section:AddButton({
			Text = 'Toggle Silent Mode', 
			Func = function()
				silent_val = not silent_val;
				if not silent_val then
					pcall(delfile, "Project Rain/silent_mode_toggle")
				else
					pcall(writefile, "Project Rain/silent_mode_toggle", "lmao")
				end;

				if silent_val then
					Logger:long_notify("Delete 'workspace/Project Rain/silent_mode_toggle' to turn this off.");
				    messagebox("You have 'Silent Mode' enabled, Which means you wont see the UI until you open it with the keybind & have extra anti PC check features, If you would like to disable this, Go to UI settings and disable it, This notification is disablable in the fast flags area of UI", "Project Rain", 0)
					messagebox("'Silent Mode' will invalidate any bug reports or support, It will disable notifications (including mod detector) which are a core part of the script as a extra side effect.", "Project Rain", 0)
				else
					aztup.silent_mode = false;
					Logger:long_notify("Disabled silent mode. I now have a voice outside of popups.");
				end;
			end,
			DoubleClick = true
		});

	end;

	function SaveManager:BuildConfigSection(tab)
		assert(self.Library, 'Must set SaveManager.Library')
		
		local section = tab:AddRightGroupbox('Configuration')
		SaveManager:BuildOtherSection(tab);
		local silent_val = isfile("Project Rain/silent_mode_toggle");
		
        section:AddLabel('Menu bind'):AddKeyPicker('MenuKeybind', { Default = 'RightAlt', NoUI = true, Text = 'Menu keybind' })

        self.Library.ToggleKeybind = aztup_options.MenuKeybind 

		section:AddInput('SaveManager_ConfigName',    { Text = 'Config name' })
		section:AddDropdown('SaveManager_ConfigList', { Text = 'Config list', Values = self:RefreshConfigList(), AllowNull = true, Searchable = true })

		section:AddDivider()

		section:AddButton('Create config', function()
			local name = aztup_options.SaveManager_ConfigName.Value

			if name:gsub(' ', '') == '' then 
				return self.Library:Notify('Invalid config name (empty)', 2)
			end

			local success, err = self:Save(name)
			if not success then
				return self.Library:NotifyWithSound('Failed to save config: ' .. err)
			end

			self.Library:NotifyWithSound(string.format('Created config %q', name))

			aztup_options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
			aztup_options.SaveManager_ConfigList:SetValue(nil)
		end):AddButton('Load config', function()
			local name = aztup_options.SaveManager_ConfigList.Value

			local success, err = self:Load(name)
			if not success then
				return self.Library:Notify('Failed to load config: ' .. err)
			end

			self.Library:NotifyWithSound(string.format('Loaded config %q', name))
		end)

		section:AddButton('Overwrite config', function()
			local name = aztup_options.SaveManager_ConfigList.Value

			local success, err = self:Save(name)
			if not success then
				return self.Library:Notify('Failed to overwrite config: ' .. err)
			end

			self.Library:NotifyWithSound(string.format('Overwrote config %q', name))
		end)


		local refresh_list_save = function()
			aztup_options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())
			aztup_options.SaveManager_ConfigList:SetValue(nil)
		end
		
		section:AddButton('Refresh list', refresh_list_save)
		getgenv().refresh_list_save = refresh_list_save;

		section:AddButton('Set as autoload (Global)', function()
			local name = aztup_options.SaveManager_ConfigList.Value
			writefile(self.Folder .. '/settings/autoload.txt', name)
			self.AutoloadLabel:SetText('Current autoload config: ' .. name)
			self.Library:NotifyWithSound(string.format('Set %q to auto load', name))
		end)
		
		section:AddButton(('Set as autoload (%s)'):format(place_name or "place"), function()
			local name = aztup_options.SaveManager_ConfigList.Value
			writefile(("%s/settings/autoload-%i.txt"):format(self.Folder, game.PlaceId), name)
			
			self.Library:NotifyWithSound(string.format('Set %q to auto load in %s', name, place_name or tostring(game.PlaceId)))
		end)

		section:AddButton('Remove Autoload (Global)', function() 
			pcall(delfile, ("%s/settings/autoload.txt"):format(self.Folder))
		end)
		
		section:AddButton(('Remove Autoload (%s)'):format(place_name or "place"), function()
			pcall(delfile, ("%s/settings/autoload-%i.txt"):format(self.Folder, game.PlaceId))
		end)


		SaveManager.AutoloadLabel = section:AddLabel('Current autoload config: none', true)
		

		if isfile(self.Folder .. '/settings/autoload.txt') then
			local name = readfile(self.Folder .. '/settings/autoload.txt')
			SaveManager.AutoloadLabel:SetText('Current autoload config: ' .. name)
		end

		if isfile(("%s/settings/autoload-%i.txt"):format(self.Folder, game.PlaceId)) then
			local name = readfile(("%s/settings/autoload-%i.txt"):format(self.Folder, game.PlaceId))
			SaveManager.AutoloadLabel:SetText('Current autoload config: ' .. name)
		end

		SaveManager:SetIgnoreIndexes({ 'SaveManager_ConfigList', 'SaveManager_ConfigName' })
	end

	SaveManager:BuildFolderTree()
end

return SaveManager
end;

