			});

			function Tabbox:AddTab(Name)
				local Tab = {};
				Tab.Window = Window;
				Tab.ParentTab = Tabbox.OwnerTab;

				local Button = Library:Create('Frame', {
					BackgroundColor3 = Library.MainColor;
					BorderColor3 = Color3.new(0, 0, 0);
					Size = UDim2.new(0.5, 0, 1, 0);
					ZIndex = 6;
					Parent = TabboxButtons;
				});

				Library:AddToRegistry(Button, {
					BackgroundColor3 = 'MainColor';
				});

				local ButtonLabel = Library:CreateLabel({
					Size = UDim2.new(1, 0, 1, 0);
					TextSize = 14;
					Text = Name;
					TextXAlignment = Enum.TextXAlignment.Center;
					ZIndex = 7;
					Parent = Button;
				});

				local Block = Library:Create('Frame', {
					BackgroundColor3 = Library.BackgroundColor;
					BorderSizePixel = 0;
					Position = UDim2.new(0, 0, 1, 0);
					Size = UDim2.new(1, 0, 0, 1);
					Visible = false;
					ZIndex = 9;
					Parent = Button;
				});

				Library:AddToRegistry(Block, {
					BackgroundColor3 = 'BackgroundColor';
				});

				local Container = Library:Create('Frame', {
					BackgroundTransparency = 1;
					Position = UDim2.new(0, 4, 0, 20);
					Size = UDim2.new(1, -4, 1, -20);
					ZIndex = 1;
					Visible = false;
					Parent = BoxInner;
				});

				Library:Create('UIListLayout', {
					FillDirection = Enum.FillDirection.Vertical;
					SortOrder = Enum.SortOrder.LayoutOrder;
					Parent = Container;
				});

				local highlight;
				Button.MouseEnter:Connect(function()
					if Container.Visible then
						return					
end

					highlight = Instance.new('Frame')
					highlight.BackgroundColor3 = Library.AccentColor
					highlight.BackgroundTransparency = 1
					highlight.BorderSizePixel = 0
					highlight.ZIndex = 9999
					highlight.Size = UDim2.new(1, 0, 1, 0)
					highlight.Parent = Button

					services.TweenService:Create(highlight, TweenInfo.new(0.18, Enum.EasingStyle.Quad), { BackgroundTransparency = 0.75 }):Play()
				end)

				
				Button.MouseLeave:Connect(function()
					if highlight then
						services.TweenService:Create(highlight, TweenInfo.new(0.18, Enum.EasingStyle.Quad), { BackgroundTransparency = 1 }):Play()
						services.Debris:AddItem(highlight, 0.18)
						highlight = nil
					end
				end)
				function Tab:Show()
					Library:CloseAllDropdowns();

					for _, Tab in next, Tabbox.Tabs do
						Tab:Hide();
					end;

					if highlight then
						services.TweenService:Create(highlight, TweenInfo.new(0.18, Enum.EasingStyle.Quad), { BackgroundTransparency = 1 }):Play()
						services.Debris:AddItem(highlight, 0.18)
						highlight = nil
					end

					Container.Visible = true;
					Block.Visible = true;

					Button.BackgroundColor3 = Library.BackgroundColor;
					Library.RegistryMap[Button].Properties.BackgroundColor3 = 'BackgroundColor';

					Tab:Resize();
				end;

				function Tab:Hide()
					Container.Visible = false;
					Block.Visible = false;

					Button.BackgroundColor3 = Library.MainColor;
					Library.RegistryMap[Button].Properties.BackgroundColor3 = 'MainColor';
				end;

				function Tab:Resize()
					local TabCount = 0;

					for _, Tab in next, Tabbox.Tabs do
						TabCount = TabCount + 1;
					end;

					for _, Button in next, TabboxButtons:GetChildren() do
						if not Button:IsA('UIListLayout') then
							Button.Size = UDim2.new(1 / TabCount, 0, 1, 0);
						end;
					end;

					if (not Container.Visible) then
						return					
end;

					local Size = 0;

					for _, Element in next, Tab.Container:GetChildren() do
						if (not Element:IsA('UIListLayout')) and Element.Visible then
							Size = Size + Element.Size.Y.Offset;
						end;
					end;

					BoxOuter.Size = UDim2.new(1, 0, 0, 20 + Size + 2 + 2);
				end;

				Button.InputBegan:Connect(function(Input)
					if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
						Tab:Show();
						Tab:Resize();
					end;
				end);

				Tab.Container = Container;
				Tab.Tabbox = Tabbox;
				TabboxTabMap[Container] = Tab;
				Tabbox.Tabs[Name] = Tab;
				Tab.Objects = {};

				setmetatable(Tab, BaseGroupbox);

				Tab:AddBlank(3);
				Tab:Resize();

				
				if #TabboxButtons:GetChildren() == 2 then
					Tab:Show();
				end;

				return Tab			
end;

			Tab.Tabboxes[Info.Name or ''] = Tabbox;
			Tabbox.OwnerTab = Tab;

			return Tabbox		
end; 

		function Tab:AddLeftTabbox(Name)
			return Tab:AddTabbox({ Name = Name, Side = 1; })		
end;

		function Tab:AddRightTabbox(Name)
			return Tab:AddTabbox({ Name = Name, Side = 2; })		
end;

		TabButton.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				Tab:ShowTab();
			end;
		end);

		
		if #TabContainer:GetChildren() == 1 then
			Tab:ShowTab();
		end;

		Window.Tabs[Name] = Tab;
		table.insert(Window.TabOrder, Tab);
		Window:ResizeTabs();
		return Tab	
end;

	
	
	
	
	
	
	
	

	local TransparencyCache = {};
	local Toggled = false;
	local Fading = false;

	function Library:Toggle()
		if Fading then
			return		
end;

		local FadeTime = Config.MenuFadeTime;
		Fading = true;
		Toggled = (not Toggled);
		uiOpen = Toggled;
		

		services.RunService:SetRobloxGuiFocused(false)
		if Toggled and aztup_toggles and aztup_toggles.BlurWhileOpen and aztup_toggles.BlurWhileOpen.Value then
			services.RunService:SetRobloxGuiFocused(true)
		end


		if FadeTime > 0 then
			for _, Desc in next, Outer:GetDescendants() do
				local Properties = {};

				if Desc:IsA('ImageLabel') then
					table.insert(Properties, 'ImageTransparency');
					table.insert(Properties, 'BackgroundTransparency');
				elseif Desc:IsA('TextLabel') or Desc:IsA('TextBox') then
					table.insert(Properties, 'TextTransparency');
				elseif Desc:IsA('Frame') or Desc:IsA('ScrollingFrame') then
					table.insert(Properties, 'BackgroundTransparency');
				elseif Desc:IsA('UIStroke') then
					table.insert(Properties, 'Transparency');
				end;

				local Cache = TransparencyCache[Desc];

				if (not Cache) then
					Cache = {};
					TransparencyCache[Desc] = Cache;
				end;

				for _, Prop in next, Properties do
					if not Cache[Prop] then
						Cache[Prop] = Desc[Prop];
					end;

					if Cache[Prop] == 1 then
						continue					
end;

					TweenService:Create(Desc, TweenInfo.new(FadeTime, Enum.EasingStyle.Linear), { [Prop] = Toggled and Cache[Prop] or 1 }):Play();
				end;
			end;
		end;

		if not Toggled then
			Library:CloseAllDropdowns();
		end;

		if FadeTime > 0 then
			task.wait(FadeTime);
		end;

		Outer.Visible = Toggled;
		Library.Toggled = Toggled;
		Library.OnToggledChanged:Fire(Toggled);

		Fading = false;
	end

	Library:GiveSignal(InputService.InputBegan:Connect(function(Input, Processed)
		if type(Library.ToggleKeybind) == 'table' and Library.ToggleKeybind.Type == 'KeyPicker' then
			if Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Library.ToggleKeybind.Value then
				task.spawn(Library.Toggle)
			end
		elseif Input.KeyCode == Enum.KeyCode.RightControl or (Input.KeyCode == Enum.KeyCode.RightShift and (not Processed)) then
			task.spawn(Library.Toggle)
		end
	end))

	if Config.AutoShow then task.spawn(Library.Toggle) end

	Window.Holder = Outer;

	return Window
end;

local function OnPlayerChange()
	local PlayerList = GetPlayersString();

	for _, Value in aztup_options do
		if Value.Type == 'Dropdown' and Value.SpecialType == 'Player' then
			Value:SetValues(PlayerList);
		end;
	end;
end;

function Library:SetInfoLoggerVisibility(Value)
	Library.InfoLoggerFrame.Visible = Value
end


function Library:UpdateInfoLoggerSize()
	if Library.InfoLoggerFrame.Visible then
		local YSize = 0
		local XSize = 0
		local items = 0;

		for _, Label in next, Library.InfoLoggerContainer:GetChildren() do
			if Label:IsA('TextLabel') and Label.Visible then
				YSize = YSize + 18;
				local LabelWidth = Label.TextBounds.X / Library:GetUIScale()
				if (LabelWidth > XSize) then
					XSize = LabelWidth
				end

				items += 1;
			end;
		end;
		
		local NewHeight = items == 0 and 24 or YSize + 32;
		local NewWidth = math.max(XSize + 34, 220);

		Library.InfoLoggerFrame.Size = UDim2.new(0, NewWidth, 0, NewHeight)
	end;
end


function Library:AddTextToInfoLogger(Text, CopyText, CopyFunc, Expiry)
	local InfoContainerLabel = Library:CreateLabel({
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new(1, 0, 0, 18),
		TextSize = 16,
		Visible = false,
		ZIndex = 110,
		Parent = Library.InfoLoggerContainer,
	}, true)

	task.spawn(function()
		InfoContainerLabel.FontFace = lexend.regular;
	end);

	if (#Library.InfoLoggerData.ContainerLabels + 1) > 15 then
		
		local FirstElement = Library.InfoLoggerData.ContainerLabels[1]
		if FirstElement then
			
			FirstElement:Destroy()

			
			table.remove(Library.InfoLoggerData.ContainerLabels, 1)
		end
	end

	InfoContainerLabel.Text = Text;

	if CopyText then
		InfoContainerLabel.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				Library:Notify("Set your clipboard to designated copyable text.");
				setclipboard(CopyText);
			end;
		end);   
	end;

	if CopyFunc then
		InfoContainerLabel.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				pcall(CopyFunc)
			end;
		end);   
	end;

	InfoContainerLabel.Visible = true
	InfoContainerLabel.TextColor3 = Library.FontColor

	Library.InfoLoggerData.ContainerLabels[#Library.InfoLoggerData.ContainerLabels + 1] = InfoContainerLabel
	Library.RegistryMap[InfoContainerLabel].Properties.TextColor3 = "FontColor"
	Library:UpdateInfoLoggerSize();

	if Expiry and type(Expiry) == "number" and Expiry > 0 then
		task.delay(Expiry, function()
			if not InfoContainerLabel or not InfoContainerLabel.Parent then
				return
			end

			local LabelIndex = table.find(Library.InfoLoggerData.ContainerLabels, InfoContainerLabel)
			if LabelIndex then
				table.remove(Library.InfoLoggerData.ContainerLabels, LabelIndex)
			end

			local FadeTime = 0.25
			local FadeTween = TweenService:Create(InfoContainerLabel, TweenInfo.new(FadeTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				TextTransparency = 1,
				TextStrokeTransparency = 1,
			})

			local TextStroke = InfoContainerLabel:FindFirstChildOfClass("UIStroke")
			if TextStroke then
				TweenService:Create(TextStroke, TweenInfo.new(FadeTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Transparency = 1,
				}):Play()
			end

			FadeTween:Play()

			task.delay(FadeTime, function()
				if InfoContainerLabel and InfoContainerLabel.Parent then
					InfoContainerLabel:Destroy()
					Library:UpdateInfoLoggerSize()
				end
			end)
		end)
	end
end 


Players.PlayerAdded:Connect(OnPlayerChange);
Players.PlayerRemoving:Connect(OnPlayerChange);
getgenv().Library = Library;
return Library


end;

modules["@src/utility/logger"] = function()






local dev_file = getgenv().dev_file or string.format("Project Rain/logs/client-%s", tostring(tick()))

if not LPH_OBFUSCATED then
    if not isfolder("Project Rain/logs") then
        makefolder("Project Rain/logs");
    end;

    if not getgenv().dev_file then
        getgenv().dev_file = dev_file;
        writefile(dev_file, "");
    end;
end;

local Logger = {} do
    function Logger:short_notify(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end; 
        local message = table.concat(args, " ");
        Library:Notify(message, 2.5);
    end

    function Logger:notify(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:Notify(message, 5);
    end
    
    function Logger:notify_sound(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:NotifyWithSound(message, 5);
    end

    function Logger:long_notify_sound(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:Notify(message, 60);
    end

    function Logger:long_notify(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:Notify(message, 60);
    end

    function Logger.log_for_devs(...)
        if LPH_OBFUSCATED then return end
        
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        
        appendfile(dev_file, "\n[l] " .. message);
    end;

    function Logger.log(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        if Library then
            Library:AddTextToInfoLogger("[I]: " .. message, "[I]: " .. message, nil)
        elseif not (aztup and aztup.silent_mode) then
            print("[I]: " .. message)
        end;
    end

    function Logger.warn(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        if Library then
            Library:AddTextToInfoLogger("[W]: " .. message, "[W]: " .. message)
        elseif not (aztup and aztup.silent_mode) then
            warn("[W]: " .. message)
        end;
    end

    function Logger.error(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        if Library then
            Library:AddTextToInfoLogger("[E]: " .. message, "[E]: " .. message)
        elseif not (aztup and aztup.silent_mode) then
            warn("[E]: " .. message)
        end;
    end
end

return Logger
end;

modules["@src/utility/loop"] = function()
return {
    run_for = function(time, callback)
        local task_conn;
        
        task_conn = services.RunService.PreSimulation:Connect(function(dt)
            if callback(dt) then
                task_conn:Disconnect();
