modules["@src/utility/maid"] = function()





local maid = {}
maid.__type = "Maid"
	


function maid.new()
	return setmetatable({
		_tasks = {},
	}, maid)
end
	


function maid:__index(index)
	if maid[index] then
		return maid[index]
	else
		return self._tasks[index]
	end
end
	



function maid:__newindex(index, new_task)
	if maid[index] ~= nil then
		return error(("'%s' is reserved"):format(tostring(index)), 2)
	end
	local tasks = self._tasks
	local old_task = tasks[index]
	if old_task == new_task then
		return
	end
	tasks[index] = new_task
	if old_task then
		if type(old_task) == "function" then
			old_task()
		elseif typeof(old_task) == "RBXScriptConnection" then
			old_task:Disconnect()
		end
		pcall(function()
			if old_task.detach then
				old_task:detach()
			end
			if old_task.Destroy then
				old_task:Destroy()
			end
		end);
	end

	return
end
	



function maid:give_task(task)
	if not task then
		return error("task cannot be false or nil", 2)
	end
	local task_id = #self._tasks + 1
	self[task_id] = task
	return task_id
end
	

function maid:remove_task(task_id)
	local tasks = self._tasks
	tasks[task_id] = nil
end


function maid:clean_task(task_id)
	
	pcall(function()
		local task = self[task_id]
		pcall(function(...)  
			if typeof(task) == "RBXScriptConnection" then
				self[task_id] = nil
				task:Disconnect()
			end
			
			
			if type(task) == "function" then
				task()
			elseif typeof(task) == "RBXScriptConnection" then
				task:Disconnect()
			elseif typeof(task) == "table" and rawget(task, "do_cleaning") then
				task:do_cleaning();
			end;
		end)
		
		pcall(function()
			if task.detach then
				task:detach()
			end
			if task.Destroy then
				task:Destroy()
			end
		end);

		self[task_id] = nil
	end)
end


function maid:do_cleaning()
	local tasks = self._tasks
	
	
	for index, task in pairs(tasks) do
		if typeof(task) == "RBXScriptConnection" then
			tasks[index] = nil
			task:Disconnect()
		end
	end
	
	
	local index, task = next(tasks)
	while task ~= nil do
		tasks[index] = nil
		if type(task) == "function" then
			task()
		elseif typeof(task) == "RBXScriptConnection" then
			task:Disconnect()
		elseif typeof(task) == "table" and rawget(task, "do_cleaning") then
			task:do_cleaning();
		end;

		pcall(function()
			if task.detach then
				task:detach()
			end
			if task.Destroy then
				task:Destroy()
			end
		end);
		index, task = next(tasks)
	end
end


return maid
end;

modules["@src/utility/markedinstancecreator"] = function()
local MarkedInstanceCreator = {}





function MarkedInstanceCreator:new(markers, instance_type, settings)
	local instance = Instance.new(instance_type)
	for index, value in settings do
		instance[index] = value
	end

	Markers:mark(instance)

	return instance
end

return MarkedInstanceCreator
end;

modules["@src/utility/markers"] = function()



local Markers = {}
Markers.__index = Markers

function Markers.new()
	return setmetatable({
		_marked_instances = {},
	}, Markers)
end

function Markers:mark(instance)
	return table.insert(self._marked_instances, instance)
end

function Markers:get()
	return self._marked_instances
end

function Markers:clear()
	for i = #self._marked_instances, 1, -1 do
		local inst = self._marked_instances[i]
		if inst then
			pcall(function()
				inst:Destroy()
			end)
		end
		self._marked_instances[i] = nil
	end
end

return Markers
end;

modules["@src/utility/persistent_data"] = function()
local storage_service = identifyexecutor() == "Synapse Z" and services.MemStorageService or services.MemStorageService;

if identifyexecutor() == "Synapse Z" then
    local existing_data = storage_service:GetItem("persistent_data");
    if not existing_data or #existing_data <= 0 then
        storage_service:SetItem("persistent_data", "{}");
    end
elseif not storage_service:HasItem("persistent_data") then
    storage_service:SetItem("persistent_data", "{}");
end

local persistent_data = {} do
    persistent_data.__index = persistent_data;
    persistent_data.current = storage_service:GetItem("persistent_data") or "{}";

    function persistent_data:wipe()
        self.current = "{}";
        storage_service:SetItem("persistent_data", self.current);
    end

    function persistent_data:set(key, value)
        local decoded = services.HttpService:JSONDecode(self.current);
        decoded[key] = value;
        
        self.current = services.HttpService:JSONEncode(decoded);
        storage_service:SetItem("persistent_data", self.current);
    end;

    function persistent_data:remove(key)
        local decoded = services.HttpService:JSONDecode(self.current);
        decoded[key] = nil;
        self.current = services.HttpService:JSONEncode(decoded);
        storage_service:SetItem("persistent_data", self.current);
    end;

    function persistent_data:get(key, or_default)
        return services.HttpService:JSONDecode(self.current)[key] or or_default    
end;
end;

return persistent_data
end;

modules["@src/utility/player-data"] = function()

local signal = require("@src/utility/signal")
local maid = require("@src/utility/maid")

local player_data = {} do
    player_data.__index = player_data

    function player_data.new()
        local self = setmetatable({}, player_data)

        self.instance = services.Players.LocalPlayer
        task.spawn(pcall, function() 
            self.character = self.instance.Character or self.instance.CharacterAdded:Wait()
        end);
        self.character_added = signal.new()
        self.root_added = signal.new()
        self.hum_added = signal.new()
        self.data_maid = maid.new()
        self.tracker = require("@src/utility/deepwoken/action_tracker").new(self);

        self.player_gui = self.instance:FindFirstChild("PlayerGui");
        self.ui_items = {}; 
        aztup.maid:give_task(self.instance.ChildAdded:Connect(function(child)
            if child.Name == "PlayerGui" then
                self.player_gui = child;
                self.ui_items = {};
            end;
        end));

        
        aztup.maid:give_task(self.data_maid)

        
        local function bind_character(character)
            
            self.data_maid:do_cleaning()

            self.character = character
            self.root_part = nil
            self.humanoid = nil

            self.character_added:fire(character)

            
            self.data_maid:give_task(character.ChildAdded:Connect(function(part)
                if part.Name == "HumanoidRootPart" then
                    self.root_part = part
                    self.root_added:fire(part)
                elseif part.Name == "Humanoid" then
                    self.humanoid = part
                    self.hum_added:fire(part)
                end
            end))

            
            self.root_part = character:FindFirstChild("HumanoidRootPart")
            self.humanoid = character:FindFirstChild("Humanoid")

            if self.root_part then
                self.root_added:fire(self.root_part)
            end
            if self.humanoid then
                self.hum_added:fire(self.humanoid)
            end
        end

        
        aztup.maid:give_task(self.instance.CharacterAdded:Connect(bind_character))

        
        if self.character then
            bind_character(self.character)
        end

        return self
    end
end

return player_data.new()
end;

